insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tu-vi-cung-menh', 'sao-cung', 'Tử Vi tại Mệnh', '{"sao":"Tử Vi","cung":"Mệnh","cachCuc":[{"c":"Mệnh","s":["Tử Vi"],"p":"dong_cung","t":"Cung Mệnh có Tử Vi miếu, vượng hay đắc địa, gặp nhiều sao tốt, được hưởng phú quý và sống lâu."},{"c":"Mệnh","s":["Tử Vi","Tuần","Triệt"],"p":"dong_cung","t":"Cung Mệnh có Tử Vi gặp Tuần, Triệt án ngữ, thường gặp khó khăn và yểu tử."},{"c":"Mệnh","s":["Tử Vi"],"p":"dong_cung","t":"Cung Mệnh có Tử Vi gặp nhiều sao mờ ám, suốt đời lao tâm khổ tứ."},{"c":"Mệnh","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Người có Tử Vi gặp Tham đồng cung thường yếm thế, cần tu hành để yên thân.","d":"Cung Mệnh an tại Mão, Dậu"},{"c":"Mệnh","s":["Tử Vi"],"p":"dong_cung","t":"Cung Mệnh có Tử Vi miếu địa hay bình hòa tọa thủ là người trung hậu.","d":"Tử miếu địa hay bình hòa"},{"c":"Mệnh","s":["Tử Vi","Thiên La","Địa Võng"],"p":"dong_cung","t":"Tử Vi cư Ngọ, vô Hình Kỵ, Giáp, Đinh, Kỷ vị chí công khanh."},{"c":"Mệnh","s":["Tử Vi"],"p":"dong_cung","t":"Cung Mệnh an tại Ngọ có Tử tọa thủ lại không bị Kình, Đà xâm phạm nên rất rực rỡ tốt đẹp.","d":"Cung Mệnh an tại Ngọ, không bị Kình, Đà xâm phạm"},{"c":"Mệnh","s":["Tử Vi"],"p":"dong_cung","t":"Đàn ông tuổi Nhâm, Giáp an tại Hợi có Tử tọa thủ nên được hưởng phú quý trọn đời. Đàn bà tuổi Nhâm, Giáp an tại Dần cũng được hưởng giàu sang.","d":"Đàn ông tuổi Nhâm, Giáp an tại Hợi; Đàn bà tuổi Nhâm, Giáp an tại Dần"},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Cung Mệnh an tại Dần, Thân có Tử Phủ tọa thủ đồng cung nên rất rực rỡ tốt đẹp.","d":"Cung Mệnh an tại Dần, Thân"},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ"],"p":"tam_hop","t":"Cung Mệnh có Tử hay Phủ tọa thủ, hay có Tử, Phủ tọa thủ đồng cung, lại gặp Phụ, Bật hội hợp nên được hưởng phú quý trọn đời."},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ","Kình Dương"],"p":"dong_cung","t":"Cung Mệnh có Tử hay Phủ, tọa thủ, gặp Kình đồng cung là người buôn bán lớn rất giàu."},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ","Vũ Khúc","Thiên Tướng"],"p":"tam_hop","t":"Cung Mệnh có Tử tọa thủ, gặp Phủ, Vũ, Tướng, Tả, Hữu, Long, Phượng, Khoa, Quyền, Lộc, Ấn hội hợp nên rất rực rỡ tốt đẹp, ví như vua tôi khánh hội ở chốn triều đình."},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ","Hóa Khoa","Hóa Quyền"],"p":"tam_hop","t":"Cung Mệnh và cung Thân có Tử, Phủ, Khoa, Quyền, Hình, Ấn, Hồng, Khôi hội hợp, rất quý hiển và được hưởng giàu sang trọn đời.","d":"Cung Mệnh và cung Thân"},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Cung Mệnh an tại Dần có Tử, Phủ tọa thủ đồng cung, gặp Kỷ, Quyền hội hợp, người có tài thao lược, lắm mưu cơ.","d":"Cung Mệnh an tại Dần"},{"c":"Mệnh","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Cung Mệnh có Tử, Tướng tọa thủ đồng cung: cung Thân có Phá tọa thủ gặp Vượng, Kình hội hợp là người lắm mưu cơ thủ đoạn, gian hùng và xảo quyệt.","d":"Cung Thân có Phá tọa thủ"},{"c":"Mệnh","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Cung Mệnh an tại Tỵ, Hợi có Tử, Sát tọa thủ đồng cung, nên được hưởng phú quý song toàn.","d":"Cung Mệnh an tại Tỵ, Hợi"},{"c":"Mệnh","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Cung Mệnh an tại Tỵ, Hợi có Tử, Sát tọa thủ đồng cung, gặp Tuần, Triệt án ngữ nên suốt đời lao khổ, chỉ có hư danh bề ngoài.","d":"Cung Mệnh an tại Tỵ, Hợi"},{"c":"Mệnh","s":["Tử Vi","Thất Sát","Hóa Quyền"],"p":"dong_cung","t":"Cung Mệnh an tại Tỵ, Hợi có Tử, Sát, Quyền, tọa thủ đồng cung, nên rất rực rỡ tốt đẹp.","d":"Cung Mệnh an tại Tỵ, Hợi"},{"c":"Mệnh","s":["Tử Vi"],"p":"dong_cung","t":"Cung Mệnh có Tử hay Vũ Miếu địa, hay đắc địa tọa thủ là người có nhiều tài năng.","d":"Tử hay Vũ Miếu địa, hay đắc địa"},{"c":"Mệnh","s":["Tử Vi","Vũ Khúc","Phá Quân"],"p":"tam_hop","t":"Cung Mệnh có Tử, Vũ hay Phá tọa thủ, lại gặp Kình, Đà hội hợp nên không thích công danh mà chỉ thích buôn bán, nhưng cũng khá giả."},{"c":"Mệnh","s":["Tử Vi","Vũ Khúc"],"p":"tam_hop","t":"Cung Mệnh có Tử hay Vũ tọa thủ, gặp nhiều Sát tinh hội hợp, tất là thầy tu hay quan lại nhỏ, nhưng lại thích được tiếng là anh hùng."},{"c":"Mệnh","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh an tại Tứ Mộ, có Tử hay Phá tọa thủ là người gian quyệt, bất trung, bất hiếu.","d":"Cung Mệnh an tại Tứ Mộ"},{"c":"Mệnh","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh an tại Thìn, Tuất, Sửu, Mùi có Tử hay Phá tọa thủ, gặp nhiều sao sáng sủa tốt đẹp hội hợp nên được hưởng phú quý đến tột bực.","d":"Cung Mệnh an tại Thìn, Tuất, Sửu, Mùi"},{"c":"Mệnh","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh an tại Sửu, có Tử, Phá tọa thủ đồng cung nếu không gặp Tả, Hữu và nhiều sao sáng sủa tốt đẹp hội hợp, tất là người gian tham độc ác.","d":"Cung Mệnh an tại Sửu"},{"c":"Mệnh","s":["Tử Vi"],"p":"dong_cung","t":"Cung Mệnh an tại Mão, Dậu, có Tử tọa thủ, gặp Kiếp, Không hội hợp là người tu hành.","d":"Cung Mệnh an tại Mão, Dậu"},{"c":"Mệnh","s":["Tử Vi"],"p":"dong_cung","t":"Cung Mệnh có Tử tọa thủ, gặp Kiếp, Không, Hồng, Đào đồng cung, nên tuổi thọ bị chiết giảm."},{"c":"Mệnh","s":["Tử Vi"],"p":"tam_hop","t":"Cung Mệnh có Tử tọa thủ, gặp Xương, Khúc hội hợp, nên được hưởng giàu sang."},{"c":"Mệnh","s":["Tử Vi","Thiên Phụ","Thiên Bật"],"p":"dong_cung","t":"Cung Mệnh có Tử, Phụ, Bật tọa thủ đồng cung, nên được hưởng phú quý, lại thêm uy quyền hiển hách."},{"c":"Mệnh","s":["Tử Vi"],"p":"tam_hop","t":"Cung Mệnh có Tử tọa thủ, cần phải Khoa, Quyền, Lộc hội hợp mới sáng sủa tốt đẹp."},{"c":"Mệnh","s":["Tử Vi"],"p":"dong_cung","t":"Cung Mệnh an tại Tý, Ngọ có Tử tọa thủ gặp Khoa, Quyền, Lộc hội chiếu nên rất sáng sủa tốt đẹp.","d":"Cung Mệnh an tại Tý, Ngọ"},{"c":"Mệnh","s":["Tử Vi"],"p":"tam_hop","t":"Cung Mệnh có Tử tọa thủ, gặp Quyền, Lộc hội hợp và bị Kình, Đà xâm phạm, cũng vẫn sáng sủa tốt đẹp."},{"c":"Mệnh","s":["Tử Vi","Hóa Lộc"],"p":"dong_cung","t":"Cung Mệnh có Tử, Lộc tọa thủ đồng cung, gặp Phụ, Bật hội chiếu nên quý hiển đến tột bực."},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ"],"p":"xung_chieu","t":"Cung Mệnh sáng sủa tốt đẹp có Tử, Phủ hội chiếu là người rất giàu, suốt đời sung túc và no ấm."},{"c":"Mệnh","s":["Thiên Phủ","Tử Vi"],"p":"dong_cung","t":"Có văn chức, uy quyền lớn, khiến mọi người phải phục tùng.","d":"Cung Mệnh hay cung Thân an tại Dần"},{"c":"Mệnh","s":["Thất Sát","Tử Vi"],"p":"dong_cung","t":"Cung Mệnh an tại Tỵ Tốn cung có Sát, Tử đồng cung, tất được hưởng phú quý đến tột bậc và có uy quyền hiển hách.","d":"Cung Mệnh an tại Tỵ Tốn cung"},{"c":"Mệnh","s":["Kình Dương","Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Kình Dương đắc địa gặp Tử, Phủ cũng đắc địa đồng cung, tất buôn bán lớn mà trở nên giàu có.","d":"Kình, Tử, Phủ đắc địa"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tu-vi-cung-phu-mau', 'sao-cung', 'Tử Vi tại Phụ Mẫu', '{"sao":"Tử Vi","cung":"Phụ Mẫu","cachCuc":[{"c":"Phụ Mẫu","s":["Tử Vi"],"p":"dong_cung","t":"Cha mẹ quý hiển, giàu có và sống lâu.","d":"Tử Vi đơn thủ tại Ngọ"},{"c":"Phụ Mẫu","s":["Tử Vi"],"p":"dong_cung","t":"Cha mẹ khá giả.","d":"Tử Vi đơn thủ tại Tý"},{"c":"Phụ Mẫu","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Cha mẹ giàu sang. Con được thừa hưởng của cha mẹ để lại rất nhiều.","d":"Tử Vi, Thiên Phủ đồng cung"},{"c":"Phụ Mẫu","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Cha mẹ vinh hiển. Gia đình yên vui, phúc lộc dồi dào.","d":"Tử Vi, Thiên Tướng đồng cung"},{"c":"Phụ Mẫu","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Cha mẹ phú quý, nhưng bất hòa. Con không hợp với tính cha mẹ. Gia đình ly tán.","d":"Tử Vi, Thất Sát đồng cung"},{"c":"Phụ Mẫu","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Trong nhà hay có sự bất hòa: cha mẹ khá giả. Nhưng sớm khắc một trong hai thân, hay phải xa cách từ lúc thiếu thời.","d":"Tử Vi, Phá Quân đồng cung"},{"c":"Phụ Mẫu","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Cha mẹ bình thường. Nên làm con nuôi họ khác. Nếu không, tất sớm xa cách một trong hai thân.","d":"Tử Vi, Tham Lang đồng cung"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tu-vi-cung-phuc-duc', 'sao-cung', 'Tử Vi tại Phúc Đức', '{"sao":"Tử Vi","cung":"Phúc Đức","cachCuc":[{"c":"Phúc Đức","s":["Tử Vi"],"p":"dong_cung","t":"Hưởng phúc lâu dài, tránh được nhiều tai họa, trong họ có nhiều người quý hiến.","d":"Tọa thủ tại Ngọ"},{"c":"Phúc Đức","s":["Tử Vi"],"p":"dong_cung","t":"Suốt đời hay gặp những sự may mắn, trong họ tuy hiếm người nhưng khá giả.","d":"Tọa thủ tại Tý"},{"c":"Phúc Đức","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Suốt đời được xứng ý toại lòng, sống lâu và hưởng phúc, họ hàng nhiều người giàu sang."},{"c":"Phúc Đức","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Suốt đời được xứng ý toại lòng, sống lâu và hưởng phúc, họ hàng nhiều người giàu sang."},{"c":"Phúc Đức","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Phải ly tổ, bôn ba mới được hưởng phúc sống lâu, trong họ có nhiều người giàu sang, hiển đạt về võ nghiệp."},{"c":"Phúc Đức","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Lao tâm khổ tứ, chẳng được yên thân, phải lìa bỏ quê hương mới khá giả và sống lâu, họ hàng ly tán."},{"c":"Phúc Đức","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Suốt đời chẳng được xứng ý toại lòng, giảm thọ vì bạc phúc, họ hàng ly tán, người nào khá giả lại chết sớm."},{"c":"Phúc Đức","s":["Tử Vi"],"p":"dong_cung","t":"Được hưởng phúc, nhưng nên lập nghiệp ở nơi thật xa quê hương. Họ hàng khá giả, có danh giá và uy quyền tế thế.","d":"Đơn thủ tại Dần, Thân"},{"c":"Phúc Đức","s":["Tử Vi"],"p":"dong_cung","t":"Không được hưởng phúc dồi dào, suốt đời may thường đi liền với rủi. Nên ly tổ có sớm xa gia đình mới mong được yên thân.","d":"Đơn thủ tại Tý, Ngọ"},{"c":"Phúc Đức","s":["Tử Vi"],"p":"dong_cung","t":"Bạc phúc nên giảm thọ. Khó tránh được lai nạn vẻ đao thương, dễ mắc hình ngục.","d":"Đơn thủ tại Thìn, Tuất"},{"c":"Phúc Đức","s":["Tử Vi"],"p":"dong_cung","t":"Phải ly tổ, bôn ba mới được hưởng phúc sống lâu. Trong họ có nhiều người giàu sang, hiển đạt về võ nghiệp.","d":"Tử Vi đồng cung"},{"c":"Phúc Đức","s":["Phá Quân","Tử Vi"],"p":"dong_cung","t":"Lao tâm khổ tứ, chẳng được yên thân. Phải lìa bỏ quê hương mới khá giả và sống lâu.","d":"Tử đồng cung"},{"c":"Phúc Đức","s":["Tử Vi"],"p":"dong_cung","t":"Giảm thọ, khó tránh được tai họa. Phải lập nghiệp ở nơi thật xa quê hương.","d":"Đồng cung"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tu-vi-cung-dien-trach', 'sao-cung', 'Tử Vi tại Điền Trạch', '{"sao":"Tử Vi","cung":"Điền Trạch","cachCuc":[{"c":"Điền Trạch","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Rất nhiều nhà đất, cơ nghiệp ngày càng thịnh vượng.","d":"Đơn thủ tại Ngọ"},{"c":"Điền Trạch","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Rất nhiều nhà đất, cơ nghiệp ngày càng thịnh vượng.","d":"Đơn thủ tại Ngọ"},{"c":"Điền Trạch","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Cơ nghiệp của tổ tiên để lại rất vĩ đại nhưng không giữ gìn được."},{"c":"Điền Trạch","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Phá tán tổ nghiệp, hay lìa bỏ tổ nghiệp. Về sau tạo lập ở nơi xa mà bền vững."},{"c":"Điền Trạch","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Không gìn giữ được tổ nghiệp, về sau sa sút."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tu-vi-cung-quan-loc', 'sao-cung', 'Tử Vi tại Quan Lộc', '{"sao":"Tử Vi","cung":"Quan Lộc","cachCuc":[{"c":"Quan Lộc","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Công danh hiển hách, phú quý song toàn.","d":"Tại Ngọ"},{"c":"Quan Lộc","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Văn võ toàn tài trước nhỏ sau lớn, có tài tổ chức, nhiều mánh lới, thủ đoạn."},{"c":"Quan Lộc","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Có uy quyền, nên chuyên về quân sự."},{"c":"Quan Lộc","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Thành công trong võ nghiệp nhưng thăng giáng thất thường."},{"c":"Quan Lộc","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Bình thường. Nếu công danh rực rỡ, tất sinh tai họa."},{"c":"Quan Lộc","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Thành công trong võ nghiệp nhưng thăng giáng thất thường. Nếu đi buôn cũng phát đạt."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tu-vi-cung-no-boc', 'sao-cung', 'Tử Vi tại Nô Bộc', '{"sao":"Tử Vi","cung":"Nô Bộc","cachCuc":[{"c":"Nô Bộc","s":["Tử Vi","Thiên Phủ","Thiên Cơ","Thái Dương","Thái Âm","Thiên Đồng","Thiên Lương"],"p":"dong_cung","t":"Người giúp việc đắc lực, đông đảo, bạn bè khá giả.","d":"sáng sủa tốt đẹp"},{"c":"Nô Bộc","s":["Thiên Phủ","Tử Vi"],"p":"dong_cung","t":"Ra ngoài luôn gặp quý nhân phù trợ, mọi sự đều hành thông, càng xa nhà càng được xứng ý toại lòng."},{"c":"Nô Bộc","s":["Tham Lang","Tử Vi"],"p":"dong_cung","t":"Rời khỏi nhà hay gặp những sự phiền lòng, may ít rủi nhiều, thường có kẻ tiểu nhân theo dõi quấy rối."},{"c":"Nô Bộc","s":["Thiên Tướng","Tử Vi"],"p":"dong_cung","t":"Được nhiều người kính nể, hay lui tới những chỗ quyền quý. Ra ngoài, được hưởng nhiều tài lộc."},{"c":"Nô Bộc","s":["Thất Sát","Tử Vi"],"p":"dong_cung","t":"Được nhiều người kính nể, hay lui tới những chỗ quyền quý. Ra ngoài, được hưởng nhiều tài lộc."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tu-vi-cung-thien-di', 'sao-cung', 'Tử Vi tại Thiên Di', '{"sao":"Tử Vi","cung":"Thiên Di","cachCuc":[{"c":"Thiên Di","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Ra ngoài luôn gặp quý nhân phù trợ, mọi sự đều hanh thông, càng xa nhà càng được xứng ý toại lòng.","d":"Đơn thủ tại Ngọ"},{"c":"Thiên Di","s":["Tử Vi"],"p":"dong_cung","t":"Gặp nhiều người giúp đỡ, nhưng không được toàn mỹ như khi ở Ngọ.","d":"Đơn thủ tại Tý"},{"c":"Thiên Di","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Được nhiều người kính nể, hay lui tới những chỗ quyền quý. Ra ngoài, được hưởng nhiều tài lộc."},{"c":"Thiên Di","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Ra ngoài nhiều hơn là ở nhà, gặp quý nhân phù trợ, nhưng lúc về già thường nhắm mắt ở xa bản quán."},{"c":"Thiên Di","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Rời khỏi nhà hay gặp những sự phiền lòng, may ít rủi nhiều, thường có kẻ tiểu nhân theo dõi quấy rối."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tu-vi-cung-tat-ach', 'sao-cung', 'Tử Vi tại Tật Ách', '{"sao":"Tử Vi","cung":"Tật Ách","cachCuc":[{"c":"Tật Ách","s":["Tử Vi"],"p":"dong_cung","t":"Cứu giải khá nhiều bệnh tật, tai ương.","d":"Phủ đồng cung, Sát đồng cung, Thiên Phủ, Thiên Lương sáng sủa tốt đẹp"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tu-vi-cung-phu-the', 'sao-cung', 'Tử Vi tại Phu Thê', '{"sao":"Tử Vi","cung":"Phu Thê","cachCuc":[{"c":"Phu Thê","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Vợ chồng hòa hợp, khá giả, chung hưởng giàu sang đến bạc đầu.","d":"Đơn thủ tại Ngọ"},{"c":"Phu Thê","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Vợ chồng cứng cỏi, ương ngạnh, ban đầu hòa hợp nhưng về sau hay xích mích."},{"c":"Phu Thê","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Tiên trở hậu thành, nên muộn lập gia đình để tránh hình khắc, chia ly."},{"c":"Phu Thê","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Phải hình khắc hay chia ly, sống chung tiếp hờn giận."},{"c":"Phu Thê","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Muộn lập gia đình mới mong được bách niên giai lao, nhưng hay có sự bất hòa."},{"c":"Phu Thê","s":["Tử Vi"],"p":"dong_cung","t":"Tiên trở hậu thành mới tránh được hình khác, chia ly."},{"c":"Phu Thê","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Phải hình khắc hay chia ly, sống chung tiếp hờn giận."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tu-vi-cung-huynh-de', 'sao-cung', 'Tử Vi tại Huynh Đệ', '{"sao":"Tử Vi","cung":"Huynh Đệ","cachCuc":[{"c":"Huynh Đệ","s":["Tử Vi","Tả Phù","Hữu Bật"],"p":"dong_cung","t":"Anh chị em khá giả, thuận hòa, nhưng có người trắc trở về hôn phối."},{"c":"Huynh Đệ","s":["Tử Vi","Tang Môn","Tả Phù","Hữu Bật"],"p":"dong_cung","t":"Anh chị em khá giả nhưng bất hòa, có người bỏ vợ hay bỏ chồng."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('liem-trinh-cung-menh', 'sao-cung', 'Liêm Trinh tại Mệnh', '{"sao":"Liêm Trinh","cung":"Mệnh","cachCuc":[{"c":"Mệnh","s":["Liêm Trinh"],"p":"tam_hop","t":"Liêm Trinh tại Mão, Dậu gặp Sát tinh, không thể mưu cầu công danh, thường chuyên về kỹ nghệ hay doanh thương.","d":"Cung Mệnh an tại Mão, Dậu"},{"c":"Mệnh","s":["Liêm Trinh"],"p":"tam_hop","t":"Liêm Trinh tại Mão, Dậu gặp Kiếp, Hình, suốt đời phải lang thang phiêu bạt.","d":"Cung Mệnh an tại Mão, Dậu"},{"c":"Mệnh","s":["Liêm Trinh"],"p":"tam_hop","t":"Liêm Trinh gặp Kình, Đà, Hỏa, Linh, hay bị bắt bớ giam cầm, có thể bị ám sát."},{"c":"Mệnh","s":["Liêm Trinh","Bạch Hổ"],"p":"dong_cung","t":"Liêm Trinh gặp Bạch Hổ, khó tránh thoát được xiềng xích gông cùm.","d":"Đồng cung hoặc xung chiếu"},{"c":"Mệnh","s":["Liêm Trinh","Tướng Quân"],"p":"dong_cung","t":"Liêm Trinh nhập Miếu hội Tướng Quân, dũng mãnh như ông Trọng Do.","d":"Đồng cung hoặc xung chiếu"},{"c":"Mệnh","s":["Tham Lang","Liêm Trinh"],"p":"dong_cung","t":"Cung Mệnh có Tham, Liêm tọa thủ đồng cung, rất mờ ám xấu xa. Đàn ông có cách này, hay chơi bời lang thang nay đây mai đó. Đàn bà có cách này rất dâm dật."},{"c":"Mệnh","s":["Tham Lang","Liêm Trinh"],"p":"dong_cung","t":"Cung Mệnh an tại Hợi (Càn) có Tham tọa thủ đồng cung, rất mờ ám xấu xa. Nếu Tham, Liêm gặp Tuyệt, Linh đồng cung, là người nghèo khổ, và nếu Tham, Liêm gặp Kình, Kiếp, Không, Hư, Mã hội hợp, thật là suốt đời cùng khốn, mà không yểu tử thì cũng cô đơn, bần hàn.","d":"Cung Mệnh an tại Hợi (Càn)"},{"c":"Mệnh","s":["Thất Sát","Liêm Trinh"],"p":"dong_cung","t":"Cung Mệnh an tại Sửu, Mùi có Sát, Liêm tọa thủ đồng cung, tất nhiên chết ở nơi giữa đường sá, hoặc vì tai nạn xe cộ, hoặc vì dao súng.","d":"Cung Mệnh an tại Sửu, Mùi"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('liem-trinh-cung-phuc-duc', 'sao-cung', 'Liêm Trinh tại Phúc Đức', '{"sao":"Liêm Trinh","cung":"Phúc Đức","cachCuc":[{"c":"Phúc Đức","s":["Liêm Trinh"],"p":"dong_cung","t":"Giảm thọ, hay gặp nguy hiểm, phải xa quê hương mới mong được an toàn. Trong họ có nhiều người chết non một cách thê thảm.","d":"Liêm đồng cung"},{"c":"Phúc Đức","s":["Phá Quân","Liêm Trinh"],"p":"dong_cung","t":"Vất vả lao khổ, phải xa quê hương mới sống lâu.","d":"Liêm đồng cung"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('liem-trinh-cung-dien-trach', 'sao-cung', 'Liêm Trinh tại Điền Trạch', '{"sao":"Liêm Trinh","cung":"Điền Trạch","cachCuc":[{"c":"Điền Trạch","s":["Liêm Trinh","Thiên Phủ"],"p":"dong_cung","t":"Được hưởng của tổ nghiệp để lại, nhưng cơ nghiệp càng về sau càng sa sút."},{"c":"Điền Trạch","s":["Liêm Trinh","Thiên Tướng"],"p":"dong_cung","t":"Nhà đất trước ít sau nhiều."},{"c":"Điền Trạch","s":["Liêm Trinh","Thất Sát"],"p":"dong_cung","t":"Tự tay lập nghiệp. Thành bại thất thường. Buổi đầu rất vất vả."},{"c":"Điền Trạch","s":["Liêm Trinh","Phá Quân"],"p":"dong_cung","t":"Lập nghiệp ở buổi đầu hay bị thất bại, phá tán. Về sau mới được bền vững."},{"c":"Điền Trạch","s":["Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Nhà đất của tổ nghiệp để lại khá nhiều, nhưng không được thừa hưởng."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('liem-trinh-cung-quan-loc', 'sao-cung', 'Liêm Trinh tại Quan Lộc', '{"sao":"Liêm Trinh","cung":"Quan Lộc","cachCuc":[{"c":"Quan Lộc","s":["Liêm Trinh","Thiên Phủ"],"p":"dong_cung","t":"Phú quý song toàn, lập được nhiều chiến công, có uy quyền hiển hách."},{"c":"Quan Lộc","s":["Liêm Trinh","Thiên Tướng"],"p":"dong_cung","t":"Văn võ kiêm toàn, được hưởng giàu sang, được nhiều người kính nể."},{"c":"Quan Lộc","s":["Liêm Trinh","Thất Sát"],"p":"dong_cung","t":"Chuyên về quân sự nhưng thăng giáng thất thường."},{"c":"Quan Lộc","s":["Liêm Trinh","Phá Quân"],"p":"dong_cung","t":"Nên chuyên về kỹ nghệ, hay thương mại."},{"c":"Quan Lộc","s":["Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Có võ chức, nhưng nhỏ thấp. Trên đường công danh thường gặp nhiều trở ngại, tai ương."},{"c":"Quan Lộc","s":["Liêm Trinh","Phá Quân"],"p":"dong_cung","t":"Nên chuyên về kỹ nghệ, hay thương mại. Nếu chen chân vào đường công danh, tất chẳng được xứng ý toại lòng."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('liem-trinh-cung-no-boc', 'sao-cung', 'Liêm Trinh tại Nô Bộc', '{"sao":"Liêm Trinh","cung":"Nô Bộc","cachCuc":[{"c":"Nô Bộc","s":["Thất Sát","Phá Quân","Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Người giúp việc đắc lực, nhưng hay lấn quyền người trên, bạn bè tài giỏi biết nâng đỡ.","d":"sáng sủa tốt đẹp"},{"c":"Nô Bộc","s":["Thiên Phủ","Liêm Trinh"],"p":"dong_cung","t":"Ra ngoài lợi ích hơn ở nhà, tài lộc dễ kiếm, quý nhân trợ giúp cũng nhiều."},{"c":"Nô Bộc","s":["Tham Lang","Liêm Trinh"],"p":"dong_cung","t":"Ra ngoài tất bít lợi, hay gặp những tai ương bất kỳ, nhất là về hình ngục hay kiện tụng."},{"c":"Nô Bộc","s":["Thiên Tướng","Liêm Trinh"],"p":"dong_cung","t":"Được nhiều người vị nể, hay lui tới những chỗ sang trọng."},{"c":"Nô Bộc","s":["Thất Sát","Liêm Trinh"],"p":"dong_cung","t":"Hay gặp tai nạn ở giữa nơi đường xá, không nên lui tới những nơi có nhiều súng ống gươm đao."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('liem-trinh-cung-thien-di', 'sao-cung', 'Liêm Trinh tại Thiên Di', '{"sao":"Liêm Trinh","cung":"Thiên Di","cachCuc":[{"c":"Thiên Di","s":["Liêm Trinh"],"p":"dong_cung","t":"Luôn luôn gặp quý nhân, được nhiều người kính trọng, mọi sự hanh thông.","d":"Đơn thủ tại Dần, Thân"},{"c":"Thiên Di","s":["Liêm Trinh","Thiên Phủ"],"p":"dong_cung","t":"Ra ngoài lợi ích hơn ở nhà, tài lộc dễ kiếm, quý nhân trợ giúp cũng nhiều."},{"c":"Thiên Di","s":["Liêm Trinh","Thiên Tướng"],"p":"dong_cung","t":"Được nhiều người vị nể, hay lui tới những chỗ sang trọng. Vì sẵn có oai phong nên những kẻ tiểu nhân mới trông thấy đã khiếp phục."},{"c":"Thiên Di","s":["Liêm Trinh","Phá Quân"],"p":"dong_cung","t":"Xa nhà không được lợi ích, may ít rủi nhiều, sau này chết ở xa nhà."},{"c":"Thiên Di","s":["Liêm Trinh","Thất Sát"],"p":"dong_cung","t":"Hay gặp tai nạn ở giữa nơi đường xá, không nên lui tới những nơi có nhiều súng ống gươm đao."},{"c":"Thiên Di","s":["Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Ra ngoài tất bít lợi, hay gặp những tai ương bất kỳ, nhất là về hình ngục hay kiện tụng."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('liem-trinh-cung-tat-ach', 'sao-cung', 'Liêm Trinh tại Tật Ách', '{"sao":"Liêm Trinh","cung":"Tật Ách","cachCuc":[{"c":"Tật Ách","s":["Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Mắt kém, hay mắc tù tội."},{"c":"Tật Ách","s":["Liêm Trinh","Tham Lang","Không","Kiếp"],"p":"dong_cung","t":"Chết một cách thê thảm."},{"c":"Tật Ách","s":["Liêm Trinh","Sát"],"p":"dong_cung","t":"Mắt rất kém, mắc tai nạn xe cộ hay đao thương."},{"c":"Tật Ách","s":["Liêm Trinh","Kỵ"],"p":"dong_cung","t":"Chết bất đắc kỳ tử, hoặc vì mắc tai nạn, hoặc vì ngộ độc.","d":"Tại Dần, Thân"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('liem-trinh-cung-tu-tuc', 'sao-cung', 'Liêm Trinh tại Tử Tức', '{"sao":"Liêm Trinh","cung":"Tử Tức","cachCuc":[{"c":"Tử Tức","s":["Thái Âm","Tham Lang","Cự Môn","Liêm Trinh","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Tử Tức có Chính diệu Bắc Đẩu tinh tọa thủ thì con gái nhiều hơn con trai.","d":"Cung Tử Tức có Chính diệu Bắc Đẩu tinh tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('liem-trinh-cung-phu-the', 'sao-cung', 'Liêm Trinh tại Phu Thê', '{"sao":"Liêm Trinh","cung":"Phu Thê","cachCuc":[{"c":"Phu Thê","s":["Liêm Trinh","Thiên Phủ"],"p":"dong_cung","t":"Nên muộn lập gia đình, vợ chồng cương cường nhưng chung sống đến bạc đầu."},{"c":"Phu Thê","s":["Liêm Trinh","Thiên Tướng"],"p":"dong_cung","t":"Vợ chồng bất hòa, nếu không tử biệt cũng sinh ly."},{"c":"Phu Thê","s":["Liêm Trinh","Thất Sát"],"p":"dong_cung","t":"Hình khắc hay sinh ly, nên muộn lập gia đình để tránh buồn thương."},{"c":"Phu Thê","s":["Liêm Trinh","Phá Quân"],"p":"dong_cung","t":"Vợ chồng bất hòa, hay xa cách, sinh kế khó khăn."},{"c":"Phu Thê","s":["Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Vợ chồng hay sinh tai họa, dễ gặp nhau lại dễ bỏ nhau."},{"c":"Phu Thê","s":["Liêm Trinh"],"p":"dong_cung","t":"Hình khắc hay sinh ly, nên muộn lập gia đình để tránh buồn thương."},{"c":"Phu Thê","s":["Liêm Trinh","Phá Quân"],"p":"dong_cung","t":"Vợ chồng bất hòa, hay xa cách nhau, sinh kế khó khăn."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('liem-trinh-cung-huynh-de', 'sao-cung', 'Liêm Trinh tại Huynh Đệ', '{"sao":"Liêm Trinh","cung":"Huynh Đệ","cachCuc":[{"c":"Huynh Đệ","s":["Thái Âm","Tham Lang","Cự Môn","Liêm Trinh","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Huynh Đệ có các sao Bắc Đẩu tinh, chị em gái nhiều hơn anh em trai.","d":"Cung Huynh Đệ có Chính diệu Bắc Đẩu tinh tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-dong-cung-menh', 'sao-cung', 'Thiên Đồng tại Mệnh', '{"sao":"Thiên Đồng","cung":"Mệnh","cachCuc":[{"c":"Mệnh","s":["Thiên Lương","Thiên Đồng"],"p":"dong_cung","t":"Đàn ông mà cung Mệnh an tại Tỵ, Hợi, có Lương hay Đồng tọa thủ, là người phóng đãng và thích phiêu lưu. Đàn bà là người dâm dật.","d":"Cung Mệnh an tại Tỵ, Hợi"},{"c":"Mệnh","s":["Thiên Lương","Thiên Đồng"],"p":"dong_cung","t":"Cung Mệnh, Thân có Lương hay Đồng miếu, vượng, đắc địa tọa thủ, hay có Lương Đồng tọa thủ đồng cung, nên suốt đời không bao giờ mắc phải tai ương họa hại.","d":"Lương hay Đồng miếu, vượng, đắc địa"},{"c":"Mệnh","s":["Thiên Lương","Thiên Đồng"],"p":"dong_cung","t":"Cung Mệnh an tại Dần, Thân, có Lương, Đồng tọa thủ đồng cung, gặp Cơ, Nguyệt hội chiếu, nên rất thông minh và được hưởng giàu sang trọn đời.","d":"Cung Mệnh an tại Dần, Thân"},{"c":"Mệnh","s":["Văn Xương","Văn Khúc","Thiên Đồng","Thiên Lương"],"p":"tam_hop","t":"Người khôn khéo, có nhiều tài năng, sớm hiển đạt và được hưởng giàu sang trọn đời."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-dong-cung-quan-loc', 'sao-cung', 'Thiên Đồng tại Quan Lộc', '{"sao":"Thiên Đồng","cung":"Quan Lộc","cachCuc":[{"c":"Quan Lộc","s":["Cự Môn","Thiên Đồng","Thiên Hình"],"p":"dong_cung","t":"Phải nhờ người trên dìu dắt mới khá giả được."},{"c":"Quan Lộc","s":["Thiên Đồng","Thái Âm","Kình Dương"],"p":"dong_cung","t":"Làm võ quan trọng trấn ở biên thùy. Lập được nhiều chiến công, hiển đạt trong thời loạn.","d":"đồng cung tại Ngọ"},{"c":"Quan Lộc","s":["Thiên Cơ","Thái Âm","Thiên Đồng","Thiên Lương"],"p":"tam_hop","t":"Nên chuyên nghề thầy thuốc, nếu dạy học cũng nổi tiếng.","d":"tại Dần, Thân, Thìn, Tuất gặp Xương, Khúc, Tả, Hữu"},{"c":"Quan Lộc","s":["Thiên Cơ","Thái Âm","Thiên Đồng","Thiên Lương"],"p":"tam_hop","t":"Vinh hiển trong nghề làm thuốc, được nhiều người kính trọng."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-dong-cung-no-boc', 'sao-cung', 'Thiên Đồng tại Nô Bộc', '{"sao":"Thiên Đồng","cung":"Nô Bộc","cachCuc":[{"c":"Nô Bộc","s":["Tử Vi","Thiên Phủ","Thiên Cơ","Thái Dương","Thái Âm","Thiên Đồng","Thiên Lương"],"p":"dong_cung","t":"Người giúp việc đắc lực, đông đảo, bạn bè khá giả.","d":"sáng sủa tốt đẹp"},{"c":"Nô Bộc","s":["Thái Âm","Thiên Đồng"],"p":"dong_cung","t":"Luôn luôn gặp quý nhân phù trợ, được nhiều người kính trọng, buôn bán phát tài.","d":"đồng cung tại Tý"},{"c":"Nô Bộc","s":["Thái Âm","Thiên Đồng"],"p":"dong_cung","t":"Hay gặp sự cạnh tranh và ghen ghét, ra ngoài rất bất lợi.","d":"đồng cung tại Ngọ"},{"c":"Nô Bộc","s":["Thiên Lương","Thiên Đồng"],"p":"dong_cung","t":"Luôn luôn gặp quý nhân phù trợ, được nhiều người kính trọng, buôn bán phát tài."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-dong-cung-tu-tuc', 'sao-cung', 'Thiên Đồng tại Tử Tức', '{"sao":"Thiên Đồng","cung":"Tử Tức","cachCuc":[{"c":"Tử Tức","s":["Thiên Phủ","Thiên Tướng","Thiên Lương","Thất Sát","Thiên Đồng","Thái Dương","Thiên Cơ"],"p":"dong_cung","t":"Cung Tử Tức có Chính diệu Nam Đẩu tinh tọa thủ thì con trai nhiều hơn con gái.","d":"Cung Tử Tức có Chính diệu Nam Đẩu tinh tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('vu-khuc-cung-menh', 'sao-cung', 'Vũ Khúc tại Mệnh', '{"sao":"Vũ Khúc","cung":"Mệnh","cachCuc":[{"c":"Mệnh","s":["Vũ Khúc"],"p":"dong_cung","t":"Cung Mệnh tuyệt địa có Vũ Khúc tọa thủ cứu giải, giúp cải thiện vận mệnh.","d":"Thủy Mệnh, cung Mệnh an tại Tỵ"},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ","Vũ Khúc","Thiên Tướng"],"p":"tam_hop","t":"Cung Mệnh có Tử tọa thủ, gặp Phủ, Vũ, Tướng, Tả, Hữu, Long, Phượng, Khoa, Quyền, Lộc, Ấn hội hợp nên rất rực rỡ tốt đẹp, ví như vua tôi khánh hội ở chốn triều đình."},{"c":"Mệnh","s":["Tử Vi","Vũ Khúc","Phá Quân"],"p":"tam_hop","t":"Cung Mệnh có Tử, Vũ hay Phá tọa thủ, lại gặp Kình, Đà hội hợp nên không thích công danh mà chỉ thích buôn bán, nhưng cũng khá giả."},{"c":"Mệnh","s":["Tử Vi","Vũ Khúc"],"p":"tam_hop","t":"Cung Mệnh có Tử hay Vũ tọa thủ, gặp nhiều Sát tinh hội hợp, tất là thầy tu hay quan lại nhỏ, nhưng lại thích được tiếng là anh hùng."},{"c":"Mệnh","s":["Vũ Khúc"],"p":"dong_cung","t":"Người có Vũ Khúc tọa thủ cung Mệnh thường cách biệt người thân, có thể khắc cha mẹ, anh em, vợ chồng hoặc con cái."},{"c":"Mệnh","s":["Vũ Khúc"],"p":"dong_cung","t":"Cung Mệnh có Vũ Khúc miếu viên tọa thủ, gặp nhiều sao tốt hội hợp, được hưởng phú quý và uy quyền.","d":"Miếu viên"},{"c":"Mệnh","s":["Vũ Khúc"],"p":"dong_cung","t":"Cung Mệnh có Vũ Khúc hãm địa tọa thủ, người chuyên về thủ công hay làm thợ.","d":"hãm địa"},{"c":"Mệnh","s":["Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh an tại Tỵ, Hợi có Vũ, Phá tọa thủ đồng cung, là người tham lận và bất lương.","d":"an tại Tỵ, Hợi"},{"c":"Mệnh","s":["Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh an tại Tỵ, Hợi có Vũ, Phá tọa thủ đồng cung nên không thể gìn giữ được của cải hay sản nghiệp của tiền nhân.","d":"an tại Tỵ, Hợi"},{"c":"Mệnh","s":["Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh có Vũ, Phá tọa thủ đồng cung, tất phải bỏ nhà đi kiếm ăn ở phương xa, và suốt đời vất vả lao khổ."},{"c":"Mệnh","s":["Vũ Khúc","Phá Quân","Văn Xương","Văn Khúc"],"p":"dong_cung","t":"Cung Mệnh có Vũ, Phá tọa thủ đồng cung, gặp Xương, Khúc đồng cung là người thông minh, khéo tay nên chuyên về kỹ nghệ máy móc."},{"c":"Mệnh","s":["Vũ Khúc","Thái Âm","Tham Lang"],"p":"dong_cung","t":"Cung Mệnh an tại Hợi có Vũ tọa thủ gặp Thái Âm và Tham Lang, cuộc đời vất vả, ít khi được xứng ý toại lòng.","d":"an tại Hợi"},{"c":"Mệnh","s":["Vũ Khúc","Tham Lang"],"p":"dong_cung","t":"Cung Mệnh, Thân an tại Sửu, Mùi có Vũ, Tham tọa thủ đồng cung, trước nghèo mà sau giàu.","d":"an tại Sửu, Mùi"},{"c":"Mệnh","s":["Vũ Khúc","Kình Dương","Đà La","Quả Tú"],"p":"dong_cung","t":"Cung Mệnh có Vũ hãm địa tọa thủ, gặp Kình, Đà, Quả hội hợp, tất vì tiền mà nguy khốn đến thân.","d":"hãm địa"},{"c":"Mệnh","s":["Vũ Khúc","Văn Khúc"],"p":"dong_cung","t":"Cung Mệnh có Vũ miếu, vượng hay đắc địa tọa thủ, gặp Khúc đồng cung, là người thông minh, học rộng, có tài năng.","d":"miếu, vượng hay đắc địa"},{"c":"Mệnh","s":["Vũ Khúc","Thiên Khôi","Thiên Việt"],"p":"dong_cung","t":"Cung Mệnh có Vũ Miếu địa hay Vượng địa tọa thủ, gặp Khôi hay Việt đồng cung, tất có quan chức về tài chính.","d":"Miếu địa hay Vượng địa"},{"c":"Mệnh","s":["Vũ Khúc","Lộc Tồn","Thiên Mã"],"p":"tam_hop","t":"Cung Mệnh có Vũ Miếu địa, hay đắc địa tọa thủ, gặp Lộc, Mã hội hợp, tất lập nghiệp ở xa quê hương, nhưng rất khá giả.","d":"Miếu địa, hay đắc địa"},{"c":"Mệnh","s":["Vũ Khúc","Lộc Tồn","Quyền"],"p":"dong_cung","t":"Cung Mệnh an tại Dần Thân, có Vũ tọa thủ, gặp Lộc, Quyền hội hợp là người rất giàu, sánh ngang với Vương Khải đời xưa.","d":"an tại Dần Thân"},{"c":"Mệnh","s":["Vũ Khúc","Địa Kiếp","Địa Không","Kình Dương"],"p":"dong_cung","t":"Cung Mệnh có Vũ hãm địa tọa thủ, gặp Kiếp Sát đồng cung gặp Kình chiếu, nên rất gian ác bất lương, giết người không biết ghê tay.","d":"hãm địa"},{"c":"Mệnh","s":["Thiên Phủ","Vũ Khúc"],"p":"dong_cung","t":"Hưởng phúc giàu sang và có danh tiếng xấu.","d":"Tuổi Giáp Đinh có cung Mệnh an tại Tý"},{"c":"Mệnh","s":["Tham Lang","Vũ Khúc"],"p":"dong_cung","t":"Cung Mệnh an tại Sửu Mùi có Tham, Vũ tọa thủ đồng cung, nên lúc thiếu thời vất vả, nghèo túng, phải từ ngoài 30 tuổi trở đi mới khá giả và càng về già lại càng giàu có.","d":"Cung Mệnh an tại Sửu Mùi"},{"c":"Mệnh","s":["Tham Lang","Vũ Khúc"],"p":"dong_cung","t":"Cung Mệnh an tại Sửu, Mùi có Tham Vũ tọa thủ đồng cung, về già có uy quyền, được nhiều người lui tới thần phục.","d":"Cung Mệnh an tại Sửu, Mùi"},{"c":"Mệnh","s":["Tham Lang","Vũ Khúc"],"p":"dong_cung","t":"Cung Mệnh an tại Tứ Mộ, có Tham tọa thủ, có Vũ tọa thủ, hay có Tham, Vũ tọa thủ đồng cung, tất phải ngoài 30 tuổi mới phát phúc và được hưởng giàu sang.","d":"Cung Mệnh an tại Tứ Mộ"},{"c":"Mệnh","s":["Tham Lang","Vũ Khúc"],"p":"dong_cung","t":"Cung Thân an tại Tứ Mộ có Tham tọa thủ, có Vũ tọa thủ, hay có Tham, Vũ tọa thủ đồng cung, là hạ cách, nên suốt đời vất vả, và không thể qúy hiển được.","d":"Cung Thân an tại Tứ Mộ"},{"c":"Mệnh","s":["Tham Lang","Vũ Khúc"],"p":"dong_cung","t":"Cung Mệnh an tại Sửu Mùi, có Tham, Vũ tọa thủ đồng cung, mà cung Mệnh lại không được sáng sủa tốt đẹp, nên rất mờ ám xấu xa. Có cách này, thật là lao khổ trọn đời.","d":"Cung Mệnh an tại Sửu Mùi"},{"c":"Mệnh","s":["Tham Lang","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh có Tham, Vũ tọa thủ đồng cung, gặp Phá chiếu, nhưng không gặp nhiều sao sáng sủa tốt đẹp hội hợp, tất hay say mê rượu ngon gái đẹp mà hại đến thân.","d":"Không gặp nhiều sao sáng sủa tốt đẹp hội hợp"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('vu-khuc-cung-phuc-duc', 'sao-cung', 'Vũ Khúc tại Phúc Đức', '{"sao":"Vũ Khúc","cung":"Phúc Đức","cachCuc":[{"c":"Phúc Đức","s":["Vũ Khúc"],"p":"dong_cung","t":"Giảm thọ vì bạc phúc. Suốt đời lao tâm khổ tứ, hay mắc tai họa.","d":"Vũ đồng cung"},{"c":"Phúc Đức","s":["Phá Quân","Vũ Khúc"],"p":"dong_cung","t":"Phải lập nghiệp ở xa quê hương, phải sớm xa gia đình mới mong được yên thân hưởng phúc sống lâu.","d":"Vũ đồng cung"},{"c":"Phúc Đức","s":["Vũ Khúc","Xương","Khúc","Khôi","Việt"],"p":"dong_cung","t":"Được hưởng phúc, sống lâu. Suốt đời gặp may mắn. Trong họ có nhiều người quý hiển."},{"c":"Phúc Đức","s":["Tham Lang","Vũ Khúc","Hỏa Tinh"],"p":"dong_cung","t":"Được hưởng phúc, tăng thêm tuổi thọ. Suốt đời hay gặp may mắn.","d":"Đồng cung Sửu, Mùi"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('vu-khuc-cung-quan-loc', 'sao-cung', 'Vũ Khúc tại Quan Lộc', '{"sao":"Vũ Khúc","cung":"Quan Lộc","cachCuc":[{"c":"Quan Lộc","s":["Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Xuất thân bằng võ nghiệp, nhưng rất chật vật. Nếu kinh doanh buôn bán, rất được xứng ý toại lòng."},{"c":"Quan Lộc","s":["Vũ Khúc","Thiên Tướng"],"p":"tam_hop","t":"Công danh hoạnh đạt, có võ chức lớn lao, có uy quyền hiển hách. Được nhiều người kính trọng và nể sợ.","d":"sáng sủa tốt đẹp"},{"c":"Quan Lộc","s":["Vũ Khúc","Thiên Tướng"],"p":"tam_hop","t":"Có danh chức, nhưng nhỏ thấp. Tuy vậy vẫn gặp được nhiều người dìu dắt, nâng đỡ.","d":"mờ ám xấu xa"},{"c":"Quan Lộc","s":["Hồng Loan","Đào Hoa","Thiên Riêu","Tấu Thư","Thiên Cơ","Vũ Khúc"],"p":"dong_cung","t":"Chuyên về múa, hát, tuồng, kịch."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('vu-khuc-cung-no-boc', 'sao-cung', 'Vũ Khúc tại Nô Bộc', '{"sao":"Vũ Khúc","cung":"Nô Bộc","cachCuc":[{"c":"Nô Bộc","s":["Vũ Khúc","Thiên Tướng"],"p":"dong_cung","t":"Người giúp việc rất tài giỏi, bạn bè quý hiển, giàu có.","d":"sáng sủa tốt đẹp"},{"c":"Nô Bộc","s":["Thiên Phủ","Vũ Khúc"],"p":"dong_cung","t":"Gặp quý nhân phù trợ, được nhiều người kính nể, tài lộc hưng vượng."},{"c":"Nô Bộc","s":["Tham Lang","Vũ Khúc"],"p":"dong_cung","t":"Buôn bán phát tài, trước khó sau dễ, hay gặp sự cạnh tranh ráo riết."},{"c":"Nô Bộc","s":["Thiên Tướng","Vũ Khúc"],"p":"dong_cung","t":"Gặp quý nhân phù trợ, được nhiều người kính nể, tài lộc hưng vượng."},{"c":"Nô Bộc","s":["Thất Sát","Vũ Khúc"],"p":"dong_cung","t":"Có oai phong, lời nói được nhiều người tin phục nhưng hay gặp những tai ương nguy hiểm."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('vu-khuc-cung-tat-ach', 'sao-cung', 'Vũ Khúc tại Tật Ách', '{"sao":"Vũ Khúc","cung":"Tật Ách","cachCuc":[{"c":"Tật Ách","s":["Thiên Khôi","Vũ Khúc"],"p":"dong_cung","t":"Mang tật ở đầu."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('vu-khuc-cung-tu-tuc', 'sao-cung', 'Vũ Khúc tại Tử Tức', '{"sao":"Vũ Khúc","cung":"Tử Tức","cachCuc":[{"c":"Tử Tức","s":["Thái Âm","Tham Lang","Cự Môn","Liêm Trinh","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Tử Tức có Chính diệu Bắc Đẩu tinh tọa thủ thì con gái nhiều hơn con trai.","d":"Cung Tử Tức có Chính diệu Bắc Đẩu tinh tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
