insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('vu-khuc-cung-huynh-de', 'sao-cung', 'Vũ Khúc tại Huynh Đệ', '{"sao":"Vũ Khúc","cung":"Huynh Đệ","cachCuc":[{"c":"Huynh Đệ","s":["Thái Âm","Tham Lang","Cự Môn","Liêm Trinh","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Huynh Đệ có các sao Bắc Đẩu tinh, chị em gái nhiều hơn anh em trai.","d":"Cung Huynh Đệ có Chính diệu Bắc Đẩu tinh tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thai-duong-cung-menh', 'sao-cung', 'Thái Dương tại Mệnh', '{"sao":"Thái Dương","cung":"Mệnh","cachCuc":[{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"xung_chieu","t":"Cung Mệnh an tại Mùi có Nhật tọa thủ tại Mão, Nguyệt tọa thủ tại Hợi, hợp chiếu, tất đi thi được đỗ cao.","d":"Cung Mệnh an tại Mùi, Nhật tọa thủ tại Mão, Nguyệt tọa thủ tại Hợi"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"xung_chieu","t":"Cung Mệnh an tại Sửu có Nhật Nguyệt tọa thủ đồng cung tại Mùi xung chiếu, là người tài giỏi quyền cao, chức trọng.","d":"Cung Mệnh an tại Sửu, Nhật Nguyệt tọa thủ đồng cung tại Mùi xung chiếu"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Cung Mệnh hay cung Thân an tại Sửu, Mùi có Nhật, Nguyệt tọa thủ đồng cung, nếu không có thêm nhiều sao sáng sủa tốt đẹp, tất bị mờ ám xấu xa.","d":"Cung Mệnh hay cung Thân an tại Sửu, Mùi có Nhật, Nguyệt tọa thủ đồng cung, tam phương vô cát"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Nhật Nguyệt rất kỵ Sát tinh, nếu gặp phải thì giảm bớt ánh sáng.","d":"Cung Mệnh an tại Sửu, Mùi có Nhật Nguyệt tọa thủ đồng cung"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Nhật Nguyệt gặp Xương, Khúc hội hợp cùng với Quý, Ấn, Thai, Tọa, Khôi, Hồng, tất là người có văn tài lỗi lạc.","d":"Cung Mệnh an tại Sửu, Mùi có Nhật Nguyệt tọa thủ đồng cung"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Nhật Nguyệt gặp Tuần, Triệt án ngữ, gặp Quý, Ân, Xương, Khúc hội chiếu, tất có sự nghiệp văn chương lớn lao.","d":"Cung Mệnh an tại Sửu, Mùi có Nhật Nguyệt tọa thủ đồng cung"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Nhật Nguyệt gặp Khoa Lộc hội hợp là người có chức vị lớn trong chính quyền.","d":"Cung Mệnh an tại Sửu có Nhật Nguyệt tọa thủ đồng cung"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"xung_chieu","t":"Nhật Nguyệt ở đây ví như mặt trời mặt trăng đua nhau chiếu sáng, suốt đời được hưởng giàu sang.","d":"Cung Mệnh an tại Thìn có Nhật tọa thủ, gặp Nguyệt tọa thủ tại Tuất xung chiếu"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"xung_chieu","t":"Cung Mệnh an tại Tuất có Nhật tọa thủ gặp Nguyệt tọa thủ tại Thìn xung chiếu, cần gặp Tuần, Triệt án ngữ hay Thiên Không đồng cung để trở nên sáng sủa tốt đẹp.","d":"Cung Mệnh an tại Tuất có Nhật tọa thủ gặp Nguyệt tọa thủ tại Thìn xung chiếu"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"xung_chieu","t":"Nhật Nguyệt gặp Xương Tuế, Lộc, Quyền, Phụ, Cáo, Tả, Hữu hội hợp, tất sớm được nhẹ bước thang mây, thành danh một cách dễ dàng.","d":"Cung Mệnh an tại Thìn, có Nhật tọa thủ, gặp Nguyệt tọa thủ tại Tuất xung chiếu"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Cung Mệnh có Nhật hãm địa tọa thủ hay có Nguyệt hãm địa tọa thủ, gặp nhiều Sát tinh hội hợp, rất xấu xa.","d":"Cung Mệnh có Nhật hãm địa tọa thủ hay có Nguyệt hãm địa tọa thủ"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Cung Mệnh có Nhật hãm địa tọa thủ hay có Nguyệt hãm địa tọa thủ, gặp Riêu, Đà, Kỵ, Kiếp, Kình hội hợp, tất bị mù lòa hai mắt.","d":"Cung Mệnh có Nhật hãm địa tọa thủ hay có Nguyệt hãm địa tọa thủ"},{"c":"Mệnh","s":["Thái Dương","Cự Môn"],"p":"xung_chieu","t":"Cung Mệnh an tại Tỵ có Nhật tọa thủ gặp Cự tọa thủ tại Hợi xung chiếu, thật là suốt đời được hưởng lộc dồi dào.","d":"Cung Mệnh an tại Tỵ có Nhật tọa thủ gặp Cự tọa thủ tại Hợi xung chiếu"},{"c":"Mệnh","s":["Thái Dương","Cự Môn"],"p":"xung_chieu","t":"Cung Mệnh an tại Hợi, có Nhật tọa thủ, gặp Cự tọa thủ tại Kỵ xung chiếu, công danh trắc trở, tiền tài khó kiếm.","d":"Cung Mệnh an tại Hợi, có Nhật tọa thủ, gặp Cự tọa thủ tại Kỵ xung chiếu"},{"c":"Mệnh","s":["Thái Dương"],"p":"dong_cung","t":"Cung Mệnh an tại Tỵ, có Nhật tọa thủ, rất sáng sủa tốt đẹp, nếu Nhật gặp Lộc, Mã, Sinh, Phụ, Bật giao hội, tất làm nên giàu có lớn trong thời bình.","d":"Cung Mệnh an tại Tỵ, có Nhật tọa thủ"},{"c":"Mệnh","s":["Thái Dương"],"p":"dong_cung","t":"Cung Mệnh an tại Hợi, có Nhật tọa thủ, không được sáng sủa tốt đẹp, nếu Nhật gặp Khoa, Quyền, Lộc chiếu, Tả, Hữu, Hồng Khôi giao hội, tất lập được kỳ công.","d":"Cung Mệnh an tại Hợi, có Nhật tọa thủ"},{"c":"Mệnh","s":["Thái Dương"],"p":"dong_cung","t":"Cung Mệnh có Nhật hãm địa tọa thủ, gặp nhiều Sát tinh hội hợp, thật là suốt đời lao khổ.","d":"Cung Mệnh có Nhật hãm địa tọa thủ"},{"c":"Mệnh","s":["Thái Dương","Hóa Kỵ"],"p":"dong_cung","t":"Cung Mệnh có Nhật, Kỵ tọa thủ đồng cung, nên hay đau mắt, mắt thường có tật.","d":"Cung Mệnh có Nhật, Kỵ tọa thủ đồng cung"},{"c":"Mệnh","s":["Thiên Lương","Thái Dương"],"p":"dong_cung","t":"Cung Mệnh an tại Mão có Lương, Nhật tọa thủ đồng cung, thật là rực rỡ tốt đẹp, ví như mặt trời mới mọc phương đông hừng sáng.","d":"Cung Mệnh an tại Mão"},{"c":"Mệnh","s":["Thiên Lương","Thái Dương"],"p":"xung_chieu","t":"Cung Mệnh an tại Tý, có Lương tọa thủ, gặp Nhật xung chiếu và Xương Lộc hội hợp, là người rất thông minh, đi thi rất đỗ cao.","d":"Cung Mệnh an tại Tý hoặc Ngọ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
