insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-co-cung-quan-loc', 'sao-cung', 'Thiên Cơ tại Quan Lộc', '{"sao":"Thiên Cơ","cung":"Quan Lộc","cachCuc":[{"c":"Quan Lộc","s":["Thiên Cơ","Thái Âm"],"p":"dong_cung","t":"Đàn bà gặp cách này hay làm nghề cô đỡ (cô mụ).","d":"đồng cung gặp Tả, Hữu hội hợp"},{"c":"Quan Lộc","s":["Thiên Cơ","Thái Âm","Thiên Đồng","Thiên Lương"],"p":"tam_hop","t":"Nên chuyên nghề thầy thuốc, nếu dạy học cũng nổi tiếng.","d":"tại Dần, Thân, Thìn, Tuất gặp Xương, Khúc, Tả, Hữu"},{"c":"Quan Lộc","s":["Thiên Cơ","Thái Âm","Thiên Đồng","Thiên Lương"],"p":"tam_hop","t":"Vinh hiển trong nghề làm thuốc, được nhiều người kính trọng."},{"c":"Quan Lộc","s":["Hồng Loan","Đào Hoa","Thiên Riêu","Tấu Thư","Thiên Cơ","Vũ Khúc"],"p":"dong_cung","t":"Chuyên về múa, hát, tuồng, kịch."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
