insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-co-cung-phu-the', 'sao-cung', 'Thiên Cơ tại Phu Thê', '{"sao":"Thiên Cơ","cung":"Phu Thê","cachCuc":[{"c":"Phu Thê","s":["Thiên Cơ"],"p":"dong_cung","t":"Sớm gặp người hiền lương, lấy nhau dễ dàng, làm ăn khá giả."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-phu-cung-menh', 'sao-cung', 'Thiên Phủ tại Mệnh', '{"sao":"Thiên Phủ","cung":"Mệnh","cachCuc":[{"c":"Mệnh","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Cung Mệnh an tại Dần, Thân có Tử Phủ tọa thủ đồng cung nên rất rực rỡ tốt đẹp.","d":"Cung Mệnh an tại Dần, Thân"},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ"],"p":"tam_hop","t":"Cung Mệnh có Tử hay Phủ tọa thủ, hay có Tử, Phủ tọa thủ đồng cung, lại gặp Phụ, Bật hội hợp nên được hưởng phú quý trọn đời."},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ","Kình Dương"],"p":"dong_cung","t":"Cung Mệnh có Tử hay Phủ, tọa thủ, gặp Kình đồng cung là người buôn bán lớn rất giàu."},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ","Vũ Khúc","Thiên Tướng"],"p":"tam_hop","t":"Cung Mệnh có Tử tọa thủ, gặp Phủ, Vũ, Tướng, Tả, Hữu, Long, Phượng, Khoa, Quyền, Lộc, Ấn hội hợp nên rất rực rỡ tốt đẹp, ví như vua tôi khánh hội ở chốn triều đình."},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ","Hóa Khoa","Hóa Quyền"],"p":"tam_hop","t":"Cung Mệnh và cung Thân có Tử, Phủ, Khoa, Quyền, Hình, Ấn, Hồng, Khôi hội hợp, rất quý hiển và được hưởng giàu sang trọn đời.","d":"Cung Mệnh và cung Thân"},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Cung Mệnh an tại Dần có Tử, Phủ tọa thủ đồng cung, gặp Kỷ, Quyền hội hợp, người có tài thao lược, lắm mưu cơ.","d":"Cung Mệnh an tại Dần"},{"c":"Mệnh","s":["Tử Vi","Thiên Phủ"],"p":"xung_chieu","t":"Cung Mệnh sáng sủa tốt đẹp có Tử, Phủ hội chiếu là người rất giàu, suốt đời sung túc và no ấm."},{"c":"Mệnh","s":["Thiên Phủ"],"p":"dong_cung","t":"Người khoan hòa, nhân hậu, có lòng từ thiện.","d":"Cung Mệnh có Phủ tọa thủ"},{"c":"Mệnh","s":["Thiên Phủ"],"p":"dong_cung","t":"Người cẩn thận, chín chắn, biết suy nghĩ sâu xa.","d":"Nam mệnh có Phủ thủ Mệnh"},{"c":"Mệnh","s":["Thiên Phủ"],"p":"dong_cung","t":"Được hưởng giàu sang trọn đời.","d":"Cung Mệnh an tại Tuất, có Phủ tọa thủ, gặp nhiều sao sáng sủa tốt đẹp hội hợp"},{"c":"Mệnh","s":["Thiên Phủ"],"p":"dong_cung","t":"Hoạnh phát công danh, hưởng phú quý đến tột bực.","d":"Cung Mệnh an tại Tuất, không bị Sát tinh xâm phạm, hợp với tuổi Giáp, Kỷ"},{"c":"Mệnh","s":["Thiên Phủ","Tử Vi"],"p":"dong_cung","t":"Có văn chức, uy quyền lớn, khiến mọi người phải phục tùng.","d":"Cung Mệnh hay cung Thân an tại Dần"},{"c":"Mệnh","s":["Thiên Phủ","Vũ Khúc"],"p":"dong_cung","t":"Hưởng phúc giàu sang và có danh tiếng xấu.","d":"Tuổi Giáp Đinh có cung Mệnh an tại Tý"},{"c":"Mệnh","s":["Thiên Phủ","Thiên Tướng"],"p":"dong_cung","t":"Có quan chức và được hưởng giàu sang.","d":"Cung Mệnh an tại Ngọ, Tuất"},{"c":"Mệnh","s":["Thiên Phủ","Thiên Tướng","Thiên Lương"],"p":"dong_cung","t":"Rực rỡ tốt đẹp, ví như vua tôi khánh hội ở chốn triều đình.","d":"Cung Mệnh có Phủ tọa thủ, gặp Tướng chiếu nhị hợp có Lương"},{"c":"Mệnh","s":["Thiên Phủ","Văn Xương","Văn Khúc"],"p":"dong_cung","t":"Được vinh hiển, có danh giá hơn người.","d":"Cung Mệnh có Phủ tọa thủ"},{"c":"Mệnh","s":["Thiên Phủ","Văn Xương","Văn Khúc","Lộc Tồn"],"p":"dong_cung","t":"Rất giàu có.","d":"Cung Mệnh có Phủ tọa thủ"},{"c":"Mệnh","s":["Thiên Phủ","Thiên Tướng"],"p":"dong_cung","t":"Rất sung túc, thừa cơm ăn áo mặc.","d":"Cung Mệnh có Phủ, Tướng hội chiếu"},{"c":"Mệnh","s":["Kình Dương","Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Kình Dương đắc địa gặp Tử, Phủ cũng đắc địa đồng cung, tất buôn bán lớn mà trở nên giàu có.","d":"Kình, Tử, Phủ đắc địa"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-phu-cung-phu-mau', 'sao-cung', 'Thiên Phủ tại Phụ Mẫu', '{"sao":"Thiên Phủ","cung":"Phụ Mẫu","cachCuc":[{"c":"Phụ Mẫu","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Cha mẹ giàu sang. Con được thừa hưởng của cha mẹ để lại rất nhiều.","d":"Tử Vi, Thiên Phủ đồng cung"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-phu-cung-phuc-duc', 'sao-cung', 'Thiên Phủ tại Phúc Đức', '{"sao":"Thiên Phủ","cung":"Phúc Đức","cachCuc":[{"c":"Phúc Đức","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Suốt đời được xứng ý toại lòng, sống lâu và hưởng phúc, họ hàng nhiều người giàu sang."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-phu-cung-dien-trach', 'sao-cung', 'Thiên Phủ tại Điền Trạch', '{"sao":"Thiên Phủ","cung":"Điền Trạch","cachCuc":[{"c":"Điền Trạch","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Rất nhiều nhà đất, cơ nghiệp ngày càng thịnh vượng.","d":"Đơn thủ tại Ngọ"},{"c":"Điền Trạch","s":["Liêm Trinh","Thiên Phủ"],"p":"dong_cung","t":"Được hưởng của tổ nghiệp để lại, nhưng cơ nghiệp càng về sau càng sa sút."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-phu-cung-quan-loc', 'sao-cung', 'Thiên Phủ tại Quan Lộc', '{"sao":"Thiên Phủ","cung":"Quan Lộc","cachCuc":[{"c":"Quan Lộc","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Công danh hiển hách, phú quý song toàn.","d":"Tại Ngọ"},{"c":"Quan Lộc","s":["Liêm Trinh","Thiên Phủ"],"p":"dong_cung","t":"Phú quý song toàn, lập được nhiều chiến công, có uy quyền hiển hách."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-phu-cung-no-boc', 'sao-cung', 'Thiên Phủ tại Nô Bộc', '{"sao":"Thiên Phủ","cung":"Nô Bộc","cachCuc":[{"c":"Nô Bộc","s":["Tử Vi","Thiên Phủ","Thiên Cơ","Thái Dương","Thái Âm","Thiên Đồng","Thiên Lương"],"p":"dong_cung","t":"Người giúp việc đắc lực, đông đảo, bạn bè khá giả.","d":"sáng sủa tốt đẹp"},{"c":"Nô Bộc","s":["Thiên Phủ"],"p":"dong_cung","t":"Gặp quý nhân, có tài lộc.","d":"đơn thủ tại Tỵ, Hợi"},{"c":"Nô Bộc","s":["Thiên Phủ"],"p":"dong_cung","t":"Xa nhà được lợi ích và yên thân hơn ở nhà, buôn bán phát tài.","d":"đơn thủ tại Sửu, Mùi, Mão, Dậu"},{"c":"Nô Bộc","s":["Thiên Phủ","Tử Vi"],"p":"dong_cung","t":"Ra ngoài luôn gặp quý nhân phù trợ, mọi sự đều hành thông, càng xa nhà càng được xứng ý toại lòng."},{"c":"Nô Bộc","s":["Thiên Phủ","Liêm Trinh"],"p":"dong_cung","t":"Ra ngoài lợi ích hơn ở nhà, tài lộc dễ kiếm, quý nhân trợ giúp cũng nhiều."},{"c":"Nô Bộc","s":["Thiên Phủ","Vũ Khúc"],"p":"dong_cung","t":"Gặp quý nhân phù trợ, được nhiều người kính nể, tài lộc hưng vượng."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-phu-cung-thien-di', 'sao-cung', 'Thiên Phủ tại Thiên Di', '{"sao":"Thiên Phủ","cung":"Thiên Di","cachCuc":[{"c":"Thiên Di","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Ra ngoài luôn gặp quý nhân phù trợ, mọi sự đều hanh thông, càng xa nhà càng được xứng ý toại lòng.","d":"Đơn thủ tại Ngọ"},{"c":"Thiên Di","s":["Liêm Trinh","Thiên Phủ"],"p":"dong_cung","t":"Ra ngoài lợi ích hơn ở nhà, tài lộc dễ kiếm, quý nhân trợ giúp cũng nhiều."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-phu-cung-tu-tuc', 'sao-cung', 'Thiên Phủ tại Tử Tức', '{"sao":"Thiên Phủ","cung":"Tử Tức","cachCuc":[{"c":"Tử Tức","s":["Thiên Phủ","Thiên Tướng","Thiên Lương","Thất Sát","Thiên Đồng","Thái Dương","Thiên Cơ"],"p":"dong_cung","t":"Cung Tử Tức có Chính diệu Nam Đẩu tinh tọa thủ thì con trai nhiều hơn con gái.","d":"Cung Tử Tức có Chính diệu Nam Đẩu tinh tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-phu-cung-phu-the', 'sao-cung', 'Thiên Phủ tại Phu Thê', '{"sao":"Thiên Phủ","cung":"Phu Thê","cachCuc":[{"c":"Phu Thê","s":["Tử Vi","Thiên Phủ"],"p":"dong_cung","t":"Vợ chồng hòa hợp, khá giả, chung hưởng giàu sang đến bạc đầu.","d":"Đơn thủ tại Ngọ"},{"c":"Phu Thê","s":["Liêm Trinh","Thiên Phủ"],"p":"dong_cung","t":"Nên muộn lập gia đình, vợ chồng cương cường nhưng chung sống đến bạc đầu."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thai-am-cung-menh', 'sao-cung', 'Thái Âm tại Mệnh', '{"sao":"Thái Âm","cung":"Mệnh","cachCuc":[{"c":"Mệnh","s":["Vũ Khúc","Thái Âm","Tham Lang"],"p":"dong_cung","t":"Cung Mệnh an tại Hợi có Vũ tọa thủ gặp Thái Âm và Tham Lang, cuộc đời vất vả, ít khi được xứng ý toại lòng.","d":"an tại Hợi"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"xung_chieu","t":"Cung Mệnh an tại Mùi có Nhật tọa thủ tại Mão, Nguyệt tọa thủ tại Hợi, hợp chiếu, tất đi thi được đỗ cao.","d":"Cung Mệnh an tại Mùi, Nhật tọa thủ tại Mão, Nguyệt tọa thủ tại Hợi"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"xung_chieu","t":"Cung Mệnh an tại Sửu có Nhật Nguyệt tọa thủ đồng cung tại Mùi xung chiếu, là người tài giỏi quyền cao, chức trọng.","d":"Cung Mệnh an tại Sửu, Nhật Nguyệt tọa thủ đồng cung tại Mùi xung chiếu"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Cung Mệnh hay cung Thân an tại Sửu, Mùi có Nhật, Nguyệt tọa thủ đồng cung, nếu không có thêm nhiều sao sáng sủa tốt đẹp, tất bị mờ ám xấu xa.","d":"Cung Mệnh hay cung Thân an tại Sửu, Mùi có Nhật, Nguyệt tọa thủ đồng cung, tam phương vô cát"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Nhật Nguyệt rất kỵ Sát tinh, nếu gặp phải thì giảm bớt ánh sáng.","d":"Cung Mệnh an tại Sửu, Mùi có Nhật Nguyệt tọa thủ đồng cung"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Nhật Nguyệt gặp Xương, Khúc hội hợp cùng với Quý, Ấn, Thai, Tọa, Khôi, Hồng, tất là người có văn tài lỗi lạc.","d":"Cung Mệnh an tại Sửu, Mùi có Nhật Nguyệt tọa thủ đồng cung"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Nhật Nguyệt gặp Tuần, Triệt án ngữ, gặp Quý, Ân, Xương, Khúc hội chiếu, tất có sự nghiệp văn chương lớn lao.","d":"Cung Mệnh an tại Sửu, Mùi có Nhật Nguyệt tọa thủ đồng cung"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Nhật Nguyệt gặp Khoa Lộc hội hợp là người có chức vị lớn trong chính quyền.","d":"Cung Mệnh an tại Sửu có Nhật Nguyệt tọa thủ đồng cung"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"xung_chieu","t":"Nhật Nguyệt ở đây ví như mặt trời mặt trăng đua nhau chiếu sáng, suốt đời được hưởng giàu sang.","d":"Cung Mệnh an tại Thìn có Nhật tọa thủ, gặp Nguyệt tọa thủ tại Tuất xung chiếu"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"xung_chieu","t":"Cung Mệnh an tại Tuất có Nhật tọa thủ gặp Nguyệt tọa thủ tại Thìn xung chiếu, cần gặp Tuần, Triệt án ngữ hay Thiên Không đồng cung để trở nên sáng sủa tốt đẹp.","d":"Cung Mệnh an tại Tuất có Nhật tọa thủ gặp Nguyệt tọa thủ tại Thìn xung chiếu"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"xung_chieu","t":"Nhật Nguyệt gặp Xương Tuế, Lộc, Quyền, Phụ, Cáo, Tả, Hữu hội hợp, tất sớm được nhẹ bước thang mây, thành danh một cách dễ dàng.","d":"Cung Mệnh an tại Thìn, có Nhật tọa thủ, gặp Nguyệt tọa thủ tại Tuất xung chiếu"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Cung Mệnh có Nhật hãm địa tọa thủ hay có Nguyệt hãm địa tọa thủ, gặp nhiều Sát tinh hội hợp, rất xấu xa.","d":"Cung Mệnh có Nhật hãm địa tọa thủ hay có Nguyệt hãm địa tọa thủ"},{"c":"Mệnh","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Cung Mệnh có Nhật hãm địa tọa thủ hay có Nguyệt hãm địa tọa thủ, gặp Riêu, Đà, Kỵ, Kiếp, Kình hội hợp, tất bị mù lòa hai mắt.","d":"Cung Mệnh có Nhật hãm địa tọa thủ hay có Nguyệt hãm địa tọa thủ"},{"c":"Mệnh","s":["Thiên Lương","Thái Âm"],"p":"xung_chieu","t":"Cung Mệnh có Lương hãm địa tọa thủ, gặp Nguyệt hợp chiếu hay có Nguyệt hãm địa tọa thủ, gặp Lương hợp chiếu, là người giang hồ, suốt đời bôn tẩu.","d":"Lương hãm địa hoặc Nguyệt hãm địa"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thai-am-cung-phu-mau', 'sao-cung', 'Thái Âm tại Phụ Mẫu', '{"sao":"Thái Âm","cung":"Phụ Mẫu","cachCuc":[{"c":"Phụ Mẫu","s":["Thái Dương","Thái Âm"],"p":"dong_cung","t":"Cha mẹ giàu sang.","d":"Đồng cung tại Sửu, Mùi"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thai-am-cung-phuc-duc', 'sao-cung', 'Thái Âm tại Phúc Đức', '{"sao":"Thái Âm","cung":"Phúc Đức","cachCuc":[{"c":"Phúc Đức","s":["Thái Dương","Thái Âm"],"p":"xung_chieu","t":"Được hưởng phúc sống lâu, tránh được nhiều tai họa.","d":"Cung Phúc Đức vô Chính diệu"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thai-am-cung-quan-loc', 'sao-cung', 'Thái Âm tại Quan Lộc', '{"sao":"Thái Âm","cung":"Quan Lộc","cachCuc":[{"c":"Quan Lộc","s":["Thiên Đồng","Thái Âm","Kình Dương"],"p":"dong_cung","t":"Làm võ quan trọng trấn ở biên thùy. Lập được nhiều chiến công, hiển đạt trong thời loạn.","d":"đồng cung tại Ngọ"},{"c":"Quan Lộc","s":["Thiên Cơ","Thái Âm"],"p":"dong_cung","t":"Đàn bà gặp cách này hay làm nghề cô đỡ (cô mụ).","d":"đồng cung gặp Tả, Hữu hội hợp"},{"c":"Quan Lộc","s":["Thiên Cơ","Thái Âm","Thiên Đồng","Thiên Lương"],"p":"tam_hop","t":"Nên chuyên nghề thầy thuốc, nếu dạy học cũng nổi tiếng.","d":"tại Dần, Thân, Thìn, Tuất gặp Xương, Khúc, Tả, Hữu"},{"c":"Quan Lộc","s":["Thiên Cơ","Thái Âm","Thiên Đồng","Thiên Lương"],"p":"tam_hop","t":"Vinh hiển trong nghề làm thuốc, được nhiều người kính trọng."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thai-am-cung-no-boc', 'sao-cung', 'Thái Âm tại Nô Bộc', '{"sao":"Thái Âm","cung":"Nô Bộc","cachCuc":[{"c":"Nô Bộc","s":["Tử Vi","Thiên Phủ","Thiên Cơ","Thái Dương","Thái Âm","Thiên Đồng","Thiên Lương"],"p":"dong_cung","t":"Người giúp việc đắc lực, đông đảo, bạn bè khá giả.","d":"sáng sủa tốt đẹp"},{"c":"Nô Bộc","s":["Thái Âm"],"p":"dong_cung","t":"Được nhiều người kính trọng, dễ kiếm tiền.","d":"đơn thủ tại Dậu, Tuất, Hợi"},{"c":"Nô Bộc","s":["Thái Âm"],"p":"dong_cung","t":"Ra ngoài hay gặp tai ương vì những sự phiền lòng, nhiều người ghét.","d":"đơn thủ tại Mão, Thìn, Tỵ"},{"c":"Nô Bộc","s":["Thái Âm","Thiên Đồng"],"p":"dong_cung","t":"Luôn luôn gặp quý nhân phù trợ, được nhiều người kính trọng, buôn bán phát tài.","d":"đồng cung tại Tý"},{"c":"Nô Bộc","s":["Thái Âm","Thiên Đồng"],"p":"dong_cung","t":"Hay gặp sự cạnh tranh và ghen ghét, ra ngoài rất bất lợi.","d":"đồng cung tại Ngọ"},{"c":"Nô Bộc","s":["Thái Âm","Thái Dương"],"p":"dong_cung","t":"Ra ngoài lợi ích hơn ở nhà, hay gần nơi quyền quý, được nhiều người tôn phục."},{"c":"Nô Bộc","s":["Thái Âm","Thiên Cơ"],"p":"dong_cung","t":"Buôn bán phát tài, nhiều người mến chuộng.","d":"đồng cung tại Thân"},{"c":"Nô Bộc","s":["Thái Âm","Thiên Cơ"],"p":"dong_cung","t":"Không nên xa nhà lâu, buôn bán phát tài nhưng bị nhiều người ghen ghét.","d":"đồng cung tại Dần"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thai-am-cung-tai-bach', 'sao-cung', 'Thái Âm tại Tài Bạch', '{"sao":"Thái Âm","cung":"Tài Bạch","cachCuc":[{"c":"Tài Bạch","s":["Thái Dương","Thái Âm"],"p":"xung_chieu","t":"Nhật, Nguyệt cùng sáng sủa xung chiếu hay hợp chiến: giàu có lớn.","d":"cung Tài Bạch vô chính diệu"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thai-am-cung-tu-tuc', 'sao-cung', 'Thái Âm tại Tử Tức', '{"sao":"Thái Âm","cung":"Tử Tức","cachCuc":[{"c":"Tử Tức","s":["Thái Âm","Tham Lang","Cự Môn","Liêm Trinh","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Tử Tức có Chính diệu Bắc Đẩu tinh tọa thủ thì con gái nhiều hơn con trai.","d":"Cung Tử Tức có Chính diệu Bắc Đẩu tinh tọa thủ"},{"c":"Tử Tức","s":["Thái Âm"],"p":"dong_cung","t":"Người sinh ban đêm, cung Tử Tức có Thái Âm mờ ám tọa thủ hay Thái Dương chiếu thì khó nuôi con.","d":"Người sinh ban đêm, cung Tử Tức có Thái Âm mờ ám tọa thủ hay Thái Dương chiếu"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thai-am-cung-huynh-de', 'sao-cung', 'Thái Âm tại Huynh Đệ', '{"sao":"Thái Âm","cung":"Huynh Đệ","cachCuc":[{"c":"Huynh Đệ","s":["Thái Âm","Tham Lang","Cự Môn","Liêm Trinh","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Huynh Đệ có các sao Bắc Đẩu tinh, chị em gái nhiều hơn anh em trai.","d":"Cung Huynh Đệ có Chính diệu Bắc Đẩu tinh tọa thủ"},{"c":"Huynh Đệ","s":["Thái Dương","Thái Âm","Thai"],"p":"dong_cung","t":"Có anh chị em sinh đôi.","d":"Tử Tức có Thai tọa thủ và có Nhật Nguyệt giáp"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tham-lang-cung-menh', 'sao-cung', 'Tham Lang tại Mệnh', '{"sao":"Tham Lang","cung":"Mệnh","cachCuc":[{"c":"Mệnh","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Người có Tử Vi gặp Tham đồng cung thường yếm thế, cần tu hành để yên thân.","d":"Cung Mệnh an tại Mão, Dậu"},{"c":"Mệnh","s":["Vũ Khúc","Thái Âm","Tham Lang"],"p":"dong_cung","t":"Cung Mệnh an tại Hợi có Vũ tọa thủ gặp Thái Âm và Tham Lang, cuộc đời vất vả, ít khi được xứng ý toại lòng.","d":"an tại Hợi"},{"c":"Mệnh","s":["Vũ Khúc","Tham Lang"],"p":"dong_cung","t":"Cung Mệnh, Thân an tại Sửu, Mùi có Vũ, Tham tọa thủ đồng cung, trước nghèo mà sau giàu.","d":"an tại Sửu, Mùi"},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Cung Mệnh có Tham Lang miếu địa tọa thủ, nên sống lâu.","d":"Tham Lang miếu địa"},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Cung Mệnh có Tham Lang hãm địa, là người vô dụng, bỏ đi.","d":"Tham Lang hãm địa"},{"c":"Mệnh","s":["Tham Lang","Vũ Khúc"],"p":"dong_cung","t":"Cung Mệnh an tại Sửu Mùi có Tham, Vũ tọa thủ đồng cung, nên lúc thiếu thời vất vả, nghèo túng, phải từ ngoài 30 tuổi trở đi mới khá giả và càng về già lại càng giàu có.","d":"Cung Mệnh an tại Sửu Mùi"},{"c":"Mệnh","s":["Tham Lang","Vũ Khúc"],"p":"dong_cung","t":"Cung Mệnh an tại Sửu, Mùi có Tham Vũ tọa thủ đồng cung, về già có uy quyền, được nhiều người lui tới thần phục.","d":"Cung Mệnh an tại Sửu, Mùi"},{"c":"Mệnh","s":["Tham Lang","Vũ Khúc"],"p":"dong_cung","t":"Cung Mệnh an tại Tứ Mộ, có Tham tọa thủ, có Vũ tọa thủ, hay có Tham, Vũ tọa thủ đồng cung, tất phải ngoài 30 tuổi mới phát phúc và được hưởng giàu sang.","d":"Cung Mệnh an tại Tứ Mộ"},{"c":"Mệnh","s":["Tham Lang","Vũ Khúc"],"p":"dong_cung","t":"Cung Thân an tại Tứ Mộ có Tham tọa thủ, có Vũ tọa thủ, hay có Tham, Vũ tọa thủ đồng cung, là hạ cách, nên suốt đời vất vả, và không thể qúy hiển được.","d":"Cung Thân an tại Tứ Mộ"},{"c":"Mệnh","s":["Tham Lang","Vũ Khúc"],"p":"dong_cung","t":"Cung Mệnh an tại Sửu Mùi, có Tham, Vũ tọa thủ đồng cung, mà cung Mệnh lại không được sáng sủa tốt đẹp, nên rất mờ ám xấu xa. Có cách này, thật là lao khổ trọn đời.","d":"Cung Mệnh an tại Sửu Mùi"},{"c":"Mệnh","s":["Tham Lang","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh có Tham, Vũ tọa thủ đồng cung, gặp Phá chiếu, nhưng không gặp nhiều sao sáng sủa tốt đẹp hội hợp, tất hay say mê rượu ngon gái đẹp mà hại đến thân.","d":"Không gặp nhiều sao sáng sủa tốt đẹp hội hợp"},{"c":"Mệnh","s":["Tham Lang","Liêm Trinh"],"p":"dong_cung","t":"Cung Mệnh có Tham, Liêm tọa thủ đồng cung, rất mờ ám xấu xa. Đàn ông có cách này, hay chơi bời lang thang nay đây mai đó. Đàn bà có cách này rất dâm dật."},{"c":"Mệnh","s":["Tham Lang","Liêm Trinh"],"p":"dong_cung","t":"Cung Mệnh an tại Hợi (Càn) có Tham tọa thủ đồng cung, rất mờ ám xấu xa. Nếu Tham, Liêm gặp Tuyệt, Linh đồng cung, là người nghèo khổ, và nếu Tham, Liêm gặp Kình, Kiếp, Không, Hư, Mã hội hợp, thật là suốt đời cùng khốn, mà không yểu tử thì cũng cô đơn, bần hàn.","d":"Cung Mệnh an tại Hợi (Càn)"},{"c":"Mệnh","s":["Tham Lang","Văn Xương"],"p":"dong_cung","t":"Cung Mệnh có Tham, Xương tọa thủ đồng cung, thường mắc bệnh bạch biến hay lang ben, da loang lổ trông rất xấu."},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Cung Mệnh có Tham hãm địa tọa thủ, gặp nhiều Sát tinh hội hợp, mà lại không gặp thêm nhiều sao sáng sủa tốt đẹp giao hội, tất phải làm nghề đồ tể, hàng thịt.","d":"Tham hãm địa"},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Cung Mệnh có Tham hãm địa tọa thủ, gặp Sát tinh đồng cung, rất mờ ám xấu xa. Đàn bà có cách này là hạng dâm dật, buôn son bán phấn. Đàn ông có cách này, là quân trộm cắp, gian giảo.","d":"Tham hãm địa"},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Cung Mệnh an tại Hợi, Tý có Tham tọa thủ, gặp Kình đồng cung, hay gặp Đà đồng cung, nên rất mờ ám xấu xa. Tham ở đây ví như hoa đào nổi trôi trên dòng nước. Có cách này, là người chơi bời, hoang đàng, thường lang thang nay đây mai đó.","d":"Cung Mệnh an tại Hợi, Tý"},{"c":"Mệnh","s":["Tham Lang","Đà La"],"p":"dong_cung","t":"Cung Mệnh an tại Dần, có Tham, Đà tọa thủ đồng cung, là người chơi bời bừa bãi, đến nỗi bị đánh đập, mang họa vào thân.","d":"Cung Mệnh an tại Dần"},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Cung Mệnh an tại Tứ Mộ, có Tham tọa thủ, hoặc gặp Hỏa đồng cung, hoặc gặp Linh đồng cung, gặp hoặc Hỏa, Linh hội hợp, là người rất giàu và có quyền cao chức trọng.","d":"Cung Mệnh an tại Tứ Mộ"},{"c":"Mệnh","s":["Tham Lang","Hỏa Tinh"],"p":"dong_cung","t":"Cung Mệnh có Tham Miếu địa ha Vượng địa tọa thủ, gặp Hỏa đồng cung, tất được hưởng phú qúy đến tột bậc và có uy danh lừng lẫy.","d":"Tham Miếu địa hay Vượng địa"},{"c":"Mệnh","s":["Tham Lang","Linh Tinh"],"p":"dong_cung","t":"Cung Mệnh có Tham Miếu địa hay Vượng địa tọa thủ, gặp Linh đồng cung, là người có tài thao lược, hiển đạt về võ nghiệp, và được hưởng giàu sang.","d":"Tham Miếu địa hay Vượng địa"},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Tham Lang rất kỵ gặp Kình, Đà, Không, Kiếp hội hợp. Nếu cung Mệnh có Tham Miếu địa hay Vượng địa tọa thủ, gặp Không đồng cung, hay Kiếp đồng cung, tất sau này không được hưởng phúc thọ song toàn, giàu thì chết sớm mà nghèo thì sống lâu.","d":"Tham Miếu địa hay Vượng địa"},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Cung Mệnh an tại Ngọ, Dần, có Tham tọa thủ, gặp Sát tinh hội hợp cùng với Hổ, Tang, thật khó mà đề phòng được sấm sét hay ác thú cắn đá.","d":"Cung Mệnh an tại Ngọ, Dần"},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Cung Mệnh an tại Hợi, Tý (Thủy cung) có Tham tọa thủ giáp Tứ Sát, thật là suốt đời nghèo khổ.","d":"Cung Mệnh an tại Hợi, Tý (Thủy cung)"},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Cung Mệnh an tại Hợi, Tý có Tham tọa thủ, gặp Quyền, Vượng hội hợp, biến hư thành thực, chuyển xấu thành tốt. Tuổi Giáp, Kỷ có cách này, được hưởng giàu sang trọng vẹn.","d":"Cung Mệnh an tại Hợi, Tý"},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Cung Mệnh có Tham Miếu địa hay Vượng địa tọa thủ, gặp Kỵ đồng cung, hay xung chiếu là người buôn bán xuôi ngược, nay đây mai đó, nhưng rất giàu.","d":"Tham Miếu địa hay Vượng địa"},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Cung Mệnh an tại Dậu (Đoài), Mão (Chấn) có Tham tọa thủ, là người thoát tục, tu hành. Nhưng trong trường hợp này, nếu Tham gặp Kỵ, Kiếp hội hợp, chắc chắn là sẽ phá giới, trở lại làm người thường, vì còn nặng nợ trần gian.","d":"Cung Mệnh an tại Dậu (Đoài), Mão (Chấn)"},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Cung Mệnh an tại Dần, Thân có Tham tọa thủ, gặp Sinh đồng cung, gặp thêm nhiều sao sáng sủa tốt đẹp hội hợp, tất sống lâu như ông Bành Tổ.","d":"Cung Mệnh an tại Dần, Thân"},{"c":"Mệnh","s":["Tham Lang","Đào Hoa"],"p":"dong_cung","t":"Đàn bà mà cung Mệnh có Tham hãm địa tọa thủ, gặp Đào đồng cung, là người độc ác thâm hiểm và rất dâm đãng. Nhưng trong trường hợp này, nếu Tham, Đào gặp Tuần, Triệt án ngữ, lại là người nhân hậu và đoan chính.","d":"Tham hãm địa"},{"c":"Mệnh","s":["Tham Lang"],"p":"dong_cung","t":"Cung Mệnh an tại Tý, có Tham tọa thủ, là hạng trộm cắp, du đãng, bất nhân, bất nghĩa. Nhưng trong trường hợp này, nếu Tham gặp Tuần, Triệt án ngữ, lại là người lương thiện, thẳng thắn và đúng mực.","d":"Cung Mệnh an tại Tý"},{"c":"Mệnh","s":["Phá Quân","Tham Lang"],"p":"dong_cung","t":"Cung Mệnh có Phá tọa thủ, gặp Lộc, Mã hội hợp: đàn ông hay chơi bời hoang đãng, đàn bà rất dâm dật.","d":"Cung Mệnh có Phá tọa thủ"},{"c":"Mệnh","s":["Địa Kiếp","Tham Lang"],"p":"dong_cung","t":"Suốt đời lao khổ, lang thang phiêu bạt, hay mắc tai nạn sông nước."},{"c":"Mệnh","s":["Đại Hao","Tham Lang"],"p":"dong_cung","t":"Người hiếu sắc dâm dật, nhưng rất kín đáo."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tham-lang-cung-phu-mau', 'sao-cung', 'Tham Lang tại Phụ Mẫu', '{"sao":"Tham Lang","cung":"Phụ Mẫu","cachCuc":[{"c":"Phụ Mẫu","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Cha mẹ bình thường. Nên làm con nuôi họ khác. Nếu không, tất sớm xa cách một trong hai thân.","d":"Tử Vi, Tham Lang đồng cung"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tham-lang-cung-phuc-duc', 'sao-cung', 'Tham Lang tại Phúc Đức', '{"sao":"Tham Lang","cung":"Phúc Đức","cachCuc":[{"c":"Phúc Đức","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Suốt đời chẳng được xứng ý toại lòng, giảm thọ vì bạc phúc, họ hàng ly tán, người nào khá giả lại chết sớm."},{"c":"Phúc Đức","s":["Tham Lang","Vũ Khúc","Hỏa Tinh"],"p":"dong_cung","t":"Được hưởng phúc, tăng thêm tuổi thọ. Suốt đời hay gặp may mắn.","d":"Đồng cung Sửu, Mùi"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tham-lang-cung-dien-trach', 'sao-cung', 'Tham Lang tại Điền Trạch', '{"sao":"Tham Lang","cung":"Điền Trạch","cachCuc":[{"c":"Điền Trạch","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Không gìn giữ được tổ nghiệp, về sau sa sút."},{"c":"Điền Trạch","s":["Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Nhà đất của tổ nghiệp để lại khá nhiều, nhưng không được thừa hưởng."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tham-lang-cung-quan-loc', 'sao-cung', 'Tham Lang tại Quan Lộc', '{"sao":"Tham Lang","cung":"Quan Lộc","cachCuc":[{"c":"Quan Lộc","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Bình thường. Nếu công danh rực rỡ, tất sinh tai họa."},{"c":"Quan Lộc","s":["Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Có võ chức, nhưng nhỏ thấp. Trên đường công danh thường gặp nhiều trở ngại, tai ương."},{"c":"Quan Lộc","s":["Tham Lang","Văn Xương"],"p":"dong_cung","t":"Có danh chức, được nhiều người biết tiếng, tài lộc dồi dào.","d":"đồng cung tại Hợi, Tý"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tham-lang-cung-no-boc', 'sao-cung', 'Tham Lang tại Nô Bộc', '{"sao":"Tham Lang","cung":"Nô Bộc","cachCuc":[{"c":"Nô Bộc","s":["Thất Sát","Phá Quân","Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Người giúp việc đắc lực, nhưng hay lấn quyền người trên, bạn bè tài giỏi biết nâng đỡ.","d":"sáng sủa tốt đẹp"},{"c":"Nô Bộc","s":["Tham Lang"],"p":"dong_cung","t":"Dễ kiếm tiền, hay gặp quý nhân.","d":"đơn thủ tại Thìn, Tuất"},{"c":"Nô Bộc","s":["Tham Lang"],"p":"dong_cung","t":"Ra ngoài rất bất lợi, hay gặp những sự phiền lòng, sau này chết ở xa nhà.","d":"đơn thủ tại Tý, Ngọ"},{"c":"Nô Bộc","s":["Tham Lang"],"p":"dong_cung","t":"Hay mắc tai nạn, xa nhà rất bất lợi.","d":"đơn thủ tại Dần, Thân"},{"c":"Nô Bộc","s":["Tham Lang","Tử Vi"],"p":"dong_cung","t":"Rời khỏi nhà hay gặp những sự phiền lòng, may ít rủi nhiều, thường có kẻ tiểu nhân theo dõi quấy rối."},{"c":"Nô Bộc","s":["Tham Lang","Vũ Khúc"],"p":"dong_cung","t":"Buôn bán phát tài, trước khó sau dễ, hay gặp sự cạnh tranh ráo riết."},{"c":"Nô Bộc","s":["Tham Lang","Liêm Trinh"],"p":"dong_cung","t":"Ra ngoài tất bít lợi, hay gặp những tai ương bất kỳ, nhất là về hình ngục hay kiện tụng."},{"c":"Nô Bộc","s":["Tham Lang","Phá Quân"],"p":"tam_hop","t":"Hay mắc tai nạn xe cộ, dao, súng. Nếu không cũng bị đánh đập giam cầm."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tham-lang-cung-thien-di', 'sao-cung', 'Tham Lang tại Thiên Di', '{"sao":"Tham Lang","cung":"Thiên Di","cachCuc":[{"c":"Thiên Di","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Rời khỏi nhà hay gặp những sự phiền lòng, may ít rủi nhiều, thường có kẻ tiểu nhân theo dõi quấy rối."},{"c":"Thiên Di","s":["Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Ra ngoài tất bít lợi, hay gặp những tai ương bất kỳ, nhất là về hình ngục hay kiện tụng."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tham-lang-cung-tat-ach', 'sao-cung', 'Tham Lang tại Tật Ách', '{"sao":"Tham Lang","cung":"Tật Ách","cachCuc":[{"c":"Tật Ách","s":["Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Mắt kém, hay mắc tù tội."},{"c":"Tật Ách","s":["Liêm Trinh","Tham Lang","Không","Kiếp"],"p":"dong_cung","t":"Chết một cách thê thảm."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tham-lang-cung-tu-tuc', 'sao-cung', 'Tham Lang tại Tử Tức', '{"sao":"Tham Lang","cung":"Tử Tức","cachCuc":[{"c":"Tử Tức","s":["Thái Âm","Tham Lang","Cự Môn","Liêm Trinh","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Tử Tức có Chính diệu Bắc Đẩu tinh tọa thủ thì con gái nhiều hơn con trai.","d":"Cung Tử Tức có Chính diệu Bắc Đẩu tinh tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tham-lang-cung-phu-the', 'sao-cung', 'Tham Lang tại Phu Thê', '{"sao":"Tham Lang","cung":"Phu Thê","cachCuc":[{"c":"Phu Thê","s":["Tử Vi","Tham Lang"],"p":"dong_cung","t":"Muộn lập gia đình mới mong được bách niên giai lao, nhưng hay có sự bất hòa."},{"c":"Phu Thê","s":["Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Vợ chồng hay sinh tai họa, dễ gặp nhau lại dễ bỏ nhau."},{"c":"Phu Thê","s":["Tham Lang","Đà La"],"p":"dong_cung","t":"Trai lấy vợ hoang đãng, gái lấy chồng ham mê tửu sắc.","d":"Đồng cung"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('tham-lang-cung-huynh-de', 'sao-cung', 'Tham Lang tại Huynh Đệ', '{"sao":"Tham Lang","cung":"Huynh Đệ","cachCuc":[{"c":"Huynh Đệ","s":["Thái Âm","Tham Lang","Cự Môn","Liêm Trinh","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Huynh Đệ có các sao Bắc Đẩu tinh, chị em gái nhiều hơn anh em trai.","d":"Cung Huynh Đệ có Chính diệu Bắc Đẩu tinh tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('cu-mon-cung-menh', 'sao-cung', 'Cự Môn tại Mệnh', '{"sao":"Cự Môn","cung":"Mệnh","cachCuc":[{"c":"Mệnh","s":["Thái Dương","Cự Môn"],"p":"xung_chieu","t":"Cung Mệnh an tại Tỵ có Nhật tọa thủ gặp Cự tọa thủ tại Hợi xung chiếu, thật là suốt đời được hưởng lộc dồi dào.","d":"Cung Mệnh an tại Tỵ có Nhật tọa thủ gặp Cự tọa thủ tại Hợi xung chiếu"},{"c":"Mệnh","s":["Thái Dương","Cự Môn"],"p":"xung_chieu","t":"Cung Mệnh an tại Hợi, có Nhật tọa thủ, gặp Cự tọa thủ tại Kỵ xung chiếu, công danh trắc trở, tiền tài khó kiếm.","d":"Cung Mệnh an tại Hợi, có Nhật tọa thủ, gặp Cự tọa thủ tại Kỵ xung chiếu"},{"c":"Mệnh","s":["Cự Môn"],"p":"dong_cung","t":"Người đa học, đa năng nhưng không gặp thời."},{"c":"Mệnh","s":["Cự Môn"],"p":"tam_hop","t":"Sống lâu nhưng không xứng ý toại lòng, thường xa cách gia đình, sức khỏe suy kém.","d":"Cự miếu, vượng hay đắc địa"},{"c":"Mệnh","s":["Cự Môn"],"p":"dong_cung","t":"Người kém thông minh, gian quyệt, tham lam, suốt đời vất vả, nhiều bệnh tật.","d":"Cự hãm địa"},{"c":"Mệnh","s":["Cự Môn"],"p":"dong_cung","t":"Người thông minh, giàu sang, không lo ngại nhiều về sự chẳng lành.","d":"Cự hãm địa, Thìn, Tuất, tuổi Quý, Tân"},{"c":"Mệnh","s":["Cự Môn"],"p":"dong_cung","t":"Người khổ sở, khốn đốn đến cùng cực.","d":"Cự hãm địa, Thìn, Tuất, tuổi Đinh, Canh"},{"c":"Mệnh","s":["Cự Môn"],"p":"dong_cung","t":"Người thông minh, học rộng, hiển đạt, khá giả.","d":"Cự hãm địa, Sửu, Mùi, tuổi Ất, Bính, Tân"},{"c":"Mệnh","s":["Cự Môn"],"p":"tam_hop","t":"Người hiểu biết sâu rộng, có văn tài, thường hoạt động chính trị.","d":"Cự hãm địa"},{"c":"Mệnh","s":["Cự Môn"],"p":"tam_hop","t":"Nên đi buôn.","d":"Cự hãm địa"},{"c":"Mệnh","s":["Cự Môn","Kỵ"],"p":"dong_cung","t":"Không thể tránh thoát tai nạn về sông nước hoặc xe cộ.","d":"Cự miếu, vượng hay đắc địa"},{"c":"Mệnh","s":["Cự Môn","Nhật"],"p":"dong_cung","t":"Từ đời ông đời cha đã vinh hiển và liên tục ba đời đều có danh giá."},{"c":"Mệnh","s":["Cự Môn","Nhật"],"p":"dong_cung","t":"Được hưởng giàu sang trọn vẹn.","d":"Cung Mệnh an tại Dần"},{"c":"Mệnh","s":["Cự Môn","Nhật"],"p":"dong_cung","t":"Khá giả, danh tài gồm đủ, nhưng không được toàn mỹ.","d":"Cung Mệnh an tại Thân"},{"c":"Mệnh","s":["Cự Môn","Nhật"],"p":"xung_chieu","t":"Quý hiển trước, rồi về sau mới phú túc.","d":"Cung Mệnh an tại Thân, xung chiếu Dần"},{"c":"Mệnh","s":["Cự Môn","Nhật"],"p":"dong_cung","t":"Rất tốt đẹp, được hưởng phú quý song toàn.","d":"Cung Mệnh an tại Dần, Thân"},{"c":"Mệnh","s":["Cự Môn","Hình"],"p":"xung_chieu","t":"Được hưởng giàu sang trọn đời."},{"c":"Mệnh","s":["Cự Môn","Cơ"],"p":"dong_cung","t":"Người thông minh, học rộng, nhưng thích chơi bời, ăn tiêu hoang phí.","d":"Cung Mệnh an tại Dần"},{"c":"Mệnh","s":["Cự Môn","Cơ"],"p":"dong_cung","t":"Chắc chắn là có quan chức lớn.","d":"Cung Mệnh an tại Dần"},{"c":"Mệnh","s":["Cự Môn","Cơ"],"p":"dong_cung","t":"Có quyền cao chức trọng.","d":"Cung Mệnh an tại Mão, Dậu, tuổi Ất, Tân, Kỷ, Bính"},{"c":"Mệnh","s":["Cự Môn","Cơ"],"p":"dong_cung","t":"Tuy cũng được hưởng phú quý, nhưng không được trọn đời.","d":"Cung Mệnh an tại Dậu"},{"c":"Mệnh","s":["Cự Môn","Cơ"],"p":"dong_cung","t":"Có uy quyền hiển hách, danh tiếng lừng lẫy.","d":"Cung Mệnh an tại Mão, Dậu"},{"c":"Mệnh","s":["Cự Môn","Đồng"],"p":"tam_hop","t":"Khó đề phòng tai nạn sông nước.","d":"Cung Mệnh an tại Tứ Mộ"},{"c":"Mệnh","s":["Cự Môn","Đồng"],"p":"tam_hop","t":"Người có tài du thuyết như Lịch Sinh đời Hán.","d":"Cung Mệnh an tại Thìn, Tuất"},{"c":"Mệnh","s":["Cự Môn"],"p":"tam_hop","t":"Suốt đời vất vả, thường mắc nhiều tật bệnh và khó tránh thoát tai họa.","d":"Cự hãm địa"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('cu-mon-cung-phuc-duc', 'sao-cung', 'Cự Môn tại Phúc Đức', '{"sao":"Cự Môn","cung":"Phúc Đức","cachCuc":[{"c":"Phúc Đức","s":["Cự Môn","Hóa Kỵ"],"p":"dong_cung","t":"Giảm thọ. Khó tránh được tai họa. Suốt đời chẳng được xứng ý toại lòng.","d":"Đồng cung"},{"c":"Phúc Đức","s":["Cự Môn","Hỏa Tinh"],"p":"dong_cung","t":"Giảm thọ, tai họa đầy rẫy. Họ hàng bất hòa ly tán và càng ngày càng suy bại.","d":"Đồng cung"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
