insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('cu-mon-cung-phu-the', 'sao-cung', 'Cự Môn tại Phu Thê', '{"sao":"Cự Môn","cung":"Phu Thê","cachCuc":[{"c":"Phu Thê","s":["Cự Môn","Hỏa Tinh"],"p":"dong_cung","t":"Mối lái rất nhiều nhưng vẫn khó tìm hôn phối."},{"c":"Phu Thê","s":["Cự Môn","Linh Tinh"],"p":"dong_cung","t":"Mối lái rất nhiều nhưng vẫn khó tìm hôn phối."},{"c":"Phu Thê","s":["Cự Môn","Hóa Kỵ","Cô Thần","Quả Tú","Kình Dương","Đà La","Linh Tinh","Tràng Sinh"],"p":"tam_hop","t":"Gái lấy nhiều chồng và có nhiều con."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('cu-mon-cung-huynh-de', 'sao-cung', 'Cự Môn tại Huynh Đệ', '{"sao":"Cự Môn","cung":"Huynh Đệ","cachCuc":[{"c":"Huynh Đệ","s":["Thái Âm","Tham Lang","Cự Môn","Liêm Trinh","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Huynh Đệ có các sao Bắc Đẩu tinh, chị em gái nhiều hơn anh em trai.","d":"Cung Huynh Đệ có Chính diệu Bắc Đẩu tinh tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-tuong-cung-menh', 'sao-cung', 'Thiên Tướng tại Mệnh', '{"sao":"Thiên Tướng","cung":"Mệnh","cachCuc":[{"c":"Mệnh","s":["Tử Vi","Thiên Phủ","Vũ Khúc","Thiên Tướng"],"p":"tam_hop","t":"Cung Mệnh có Tử tọa thủ, gặp Phủ, Vũ, Tướng, Tả, Hữu, Long, Phượng, Khoa, Quyền, Lộc, Ấn hội hợp nên rất rực rỡ tốt đẹp, ví như vua tôi khánh hội ở chốn triều đình."},{"c":"Mệnh","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Cung Mệnh có Tử, Tướng tọa thủ đồng cung: cung Thân có Phá tọa thủ gặp Vượng, Kình hội hợp là người lắm mưu cơ thủ đoạn, gian hùng và xảo quyệt.","d":"Cung Thân có Phá tọa thủ"},{"c":"Mệnh","s":["Thiên Phủ","Thiên Tướng"],"p":"dong_cung","t":"Có quan chức và được hưởng giàu sang.","d":"Cung Mệnh an tại Ngọ, Tuất"},{"c":"Mệnh","s":["Thiên Phủ","Thiên Tướng","Thiên Lương"],"p":"dong_cung","t":"Rực rỡ tốt đẹp, ví như vua tôi khánh hội ở chốn triều đình.","d":"Cung Mệnh có Phủ tọa thủ, gặp Tướng chiếu nhị hợp có Lương"},{"c":"Mệnh","s":["Thiên Phủ","Thiên Tướng"],"p":"dong_cung","t":"Rất sung túc, thừa cơm ăn áo mặc.","d":"Cung Mệnh có Phủ, Tướng hội chiếu"},{"c":"Mệnh","s":["Thiên Tướng"],"p":"dong_cung","t":"Cung Mệnh an tại Thìn, Tuất có Thiên Tướng tọa thủ, nên rất quý hiển.","d":"Cung Mệnh an tại Thìn, Tuất"},{"c":"Mệnh","s":["Thiên Tướng"],"p":"dong_cung","t":"Đàn bà mà cung Mệnh có Tướng tọa thủ, nên rất can đảm, dũng mãnh.","d":"Nữ mệnh"},{"c":"Mệnh","s":["Thiên Tướng","Hồng Loan"],"p":"dong_cung","t":"Đàn bà mà cung Mệnh có Tướng, Hồng, tọa thủ đồng cung, tất lấy được chồng giàu sang.","d":"Nữ mệnh"},{"c":"Mệnh","s":["Thiên Tướng"],"p":"tam_hop","t":"Đàn bà mà cung Mệnh có Tướng tọa thủ, gặp Khúc, Mộc, Cái, Đào hội hợp, nên rất xinh đẹp, nhưng lại có tính dâm đãng.","d":"Nữ mệnh"},{"c":"Mệnh","s":["Địa Kiếp","Địa Không","Thiên Tướng","Thiên Mã","Hóa Khoa"],"p":"dong_cung","t":"Người tài giỏi, lập nên sự nghiệp lớn trong thời loạn.","d":"Tỵ, Hợi"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-tuong-cung-phu-mau', 'sao-cung', 'Thiên Tướng tại Phụ Mẫu', '{"sao":"Thiên Tướng","cung":"Phụ Mẫu","cachCuc":[{"c":"Phụ Mẫu","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Cha mẹ vinh hiển. Gia đình yên vui, phúc lộc dồi dào.","d":"Tử Vi, Thiên Tướng đồng cung"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-tuong-cung-phuc-duc', 'sao-cung', 'Thiên Tướng tại Phúc Đức', '{"sao":"Thiên Tướng","cung":"Phúc Đức","cachCuc":[{"c":"Phúc Đức","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Suốt đời được xứng ý toại lòng, sống lâu và hưởng phúc, họ hàng nhiều người giàu sang."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-tuong-cung-dien-trach', 'sao-cung', 'Thiên Tướng tại Điền Trạch', '{"sao":"Thiên Tướng","cung":"Điền Trạch","cachCuc":[{"c":"Điền Trạch","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Rất nhiều nhà đất, cơ nghiệp ngày càng thịnh vượng.","d":"Đơn thủ tại Ngọ"},{"c":"Điền Trạch","s":["Liêm Trinh","Thiên Tướng"],"p":"dong_cung","t":"Nhà đất trước ít sau nhiều."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-tuong-cung-quan-loc', 'sao-cung', 'Thiên Tướng tại Quan Lộc', '{"sao":"Thiên Tướng","cung":"Quan Lộc","cachCuc":[{"c":"Quan Lộc","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Văn võ toàn tài trước nhỏ sau lớn, có tài tổ chức, nhiều mánh lới, thủ đoạn."},{"c":"Quan Lộc","s":["Liêm Trinh","Thiên Tướng"],"p":"dong_cung","t":"Văn võ kiêm toàn, được hưởng giàu sang, được nhiều người kính nể."},{"c":"Quan Lộc","s":["Vũ Khúc","Thiên Tướng"],"p":"tam_hop","t":"Công danh hoạnh đạt, có võ chức lớn lao, có uy quyền hiển hách. Được nhiều người kính trọng và nể sợ.","d":"sáng sủa tốt đẹp"},{"c":"Quan Lộc","s":["Vũ Khúc","Thiên Tướng"],"p":"tam_hop","t":"Có danh chức, nhưng nhỏ thấp. Tuy vậy vẫn gặp được nhiều người dìu dắt, nâng đỡ.","d":"mờ ám xấu xa"},{"c":"Quan Lộc","s":["Thiên Tướng","Tấu Thư","Phù"],"p":"dong_cung","t":"Làm thầy chùa hay phủ thủy (thầy pháp).","d":"Mệnh có Tả, Hữu tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-tuong-cung-no-boc', 'sao-cung', 'Thiên Tướng tại Nô Bộc', '{"sao":"Thiên Tướng","cung":"Nô Bộc","cachCuc":[{"c":"Nô Bộc","s":["Vũ Khúc","Thiên Tướng"],"p":"dong_cung","t":"Người giúp việc rất tài giỏi, bạn bè quý hiển, giàu có.","d":"sáng sủa tốt đẹp"},{"c":"Nô Bộc","s":["Tả Phụ","Hữu Bật","Thiên Tướng","Phục Binh"],"p":"dong_cung","t":"Người giúp việc đắc lực, tận tâm và trung thành, bạn bè tốt."},{"c":"Nô Bộc","s":["Thiên Tướng"],"p":"dong_cung","t":"Được nhiều người kính trọng, tài lộc dễ kiếm.","d":"đơn thủ tại Tỵ, Hợi, Sửu, Mùi"},{"c":"Nô Bộc","s":["Thiên Tướng"],"p":"dong_cung","t":"Xa nhà không được lợi ích tuy vậy vẫn được nhiều người mến chuộng.","d":"đơn thủ tại Mão, Dậu"},{"c":"Nô Bộc","s":["Thiên Tướng","Tử Vi"],"p":"dong_cung","t":"Được nhiều người kính nể, hay lui tới những chỗ quyền quý. Ra ngoài, được hưởng nhiều tài lộc."},{"c":"Nô Bộc","s":["Thiên Tướng","Liêm Trinh"],"p":"dong_cung","t":"Được nhiều người vị nể, hay lui tới những chỗ sang trọng."},{"c":"Nô Bộc","s":["Thiên Tướng","Vũ Khúc"],"p":"dong_cung","t":"Gặp quý nhân phù trợ, được nhiều người kính nể, tài lộc hưng vượng."},{"c":"Nô Bộc","s":["Tướng Quân","Thiên Tướng"],"p":"tam_hop","t":"Chết vì tai nạn xe cộ hay bị giết."},{"c":"Nô Bộc","s":["Thiên Tướng","Phục Binh","Hồng Loan","Đào Hoa"],"p":"tam_hop","t":"Tơ duyên rắc rối, hay mắc lừa vì tình."},{"c":"Nô Bộc","s":["Thai","Vượng","Thiên Tướng","Phục Binh","Hồng Loan","Đào Hoa"],"p":"tam_hop","t":"Đàn ông ra ngoài hay vướng vào lưới tình vì đắm mê sắc dục mà hại đến thân. Đàn bà ra ngoài khó giữ được toàn danh tiết."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-tuong-cung-thien-di', 'sao-cung', 'Thiên Tướng tại Thiên Di', '{"sao":"Thiên Tướng","cung":"Thiên Di","cachCuc":[{"c":"Thiên Di","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Được nhiều người kính nể, hay lui tới những chỗ quyền quý. Ra ngoài, được hưởng nhiều tài lộc."},{"c":"Thiên Di","s":["Liêm Trinh","Thiên Tướng"],"p":"dong_cung","t":"Được nhiều người vị nể, hay lui tới những chỗ sang trọng. Vì sẵn có oai phong nên những kẻ tiểu nhân mới trông thấy đã khiếp phục."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-tuong-cung-tu-tuc', 'sao-cung', 'Thiên Tướng tại Tử Tức', '{"sao":"Thiên Tướng","cung":"Tử Tức","cachCuc":[{"c":"Tử Tức","s":["Thiên Phủ","Thiên Tướng","Thiên Lương","Thất Sát","Thiên Đồng","Thái Dương","Thiên Cơ"],"p":"dong_cung","t":"Cung Tử Tức có Chính diệu Nam Đẩu tinh tọa thủ thì con trai nhiều hơn con gái.","d":"Cung Tử Tức có Chính diệu Nam Đẩu tinh tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-tuong-cung-phu-the', 'sao-cung', 'Thiên Tướng tại Phu Thê', '{"sao":"Thiên Tướng","cung":"Phu Thê","cachCuc":[{"c":"Phu Thê","s":["Tử Vi","Thiên Tướng"],"p":"dong_cung","t":"Vợ chồng cứng cỏi, ương ngạnh, ban đầu hòa hợp nhưng về sau hay xích mích."},{"c":"Phu Thê","s":["Liêm Trinh","Thiên Tướng"],"p":"dong_cung","t":"Vợ chồng bất hòa, nếu không tử biệt cũng sinh ly."},{"c":"Phu Thê","s":["Thiên Tướng","Đào Hoa","Hồng Loan"],"p":"dong_cung","t":"Trai lấy vợ đẹp, khá giả, gái lấy chồng hiền, danh giá.","d":"Đồng cung"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-tuong-cung-huynh-de', 'sao-cung', 'Thiên Tướng tại Huynh Đệ', '{"sao":"Thiên Tướng","cung":"Huynh Đệ","cachCuc":[{"c":"Huynh Đệ","s":["Phá Quân","Thiên Tướng"],"p":"dong_cung","t":"Anh chị em có người không đứng đắn, ưa việc liễu ngõ hoa tường."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-luong-cung-menh', 'sao-cung', 'Thiên Lương tại Mệnh', '{"sao":"Thiên Lương","cung":"Mệnh","cachCuc":[{"c":"Mệnh","s":["Thiên Phủ","Thiên Tướng","Thiên Lương"],"p":"dong_cung","t":"Rực rỡ tốt đẹp, ví như vua tôi khánh hội ở chốn triều đình.","d":"Cung Mệnh có Phủ tọa thủ, gặp Tướng chiếu nhị hợp có Lương"},{"c":"Mệnh","s":["Thiên Lương"],"p":"dong_cung","t":"Cung Mệnh có Lương miếu, vượng hay đắc địa tọa thủ, hay chiếu lại gặp nhiều sao sáng sủa tốt đẹp hội hợp, nên được hưởng phúc và sống lâu.","d":"Lương miếu, vượng hay đắc địa"},{"c":"Mệnh","s":["Thiên Lương"],"p":"dong_cung","t":"Cung Mệnh an tại Ngọ có Lương tọa thủ, nên rất rực rỡ tốt đẹp. Tuổi Đinh, Kỷ, Qúy có cách này, tất được hưởng phú quý đến tột bậc.","d":"Cung Mệnh an tại Ngọ"},{"c":"Mệnh","s":["Thiên Lương","Thái Dương"],"p":"dong_cung","t":"Cung Mệnh an tại Mão có Lương, Nhật tọa thủ đồng cung, thật là rực rỡ tốt đẹp, ví như mặt trời mới mọc phương đông hừng sáng.","d":"Cung Mệnh an tại Mão"},{"c":"Mệnh","s":["Thiên Lương","Thái Dương"],"p":"xung_chieu","t":"Cung Mệnh an tại Tý, có Lương tọa thủ, gặp Nhật xung chiếu và Xương Lộc hội hợp, là người rất thông minh, đi thi rất đỗ cao.","d":"Cung Mệnh an tại Tý hoặc Ngọ"},{"c":"Mệnh","s":["Thiên Lương","Thái Âm"],"p":"xung_chieu","t":"Cung Mệnh có Lương hãm địa tọa thủ, gặp Nguyệt hợp chiếu hay có Nguyệt hãm địa tọa thủ, gặp Lương hợp chiếu, là người giang hồ, suốt đời bôn tẩu.","d":"Lương hãm địa hoặc Nguyệt hãm địa"},{"c":"Mệnh","s":["Thiên Lương"],"p":"tam_hop","t":"Cung Mệnh an tại Tý, Sửu, Dần, Mão, Thìn, Tỵ, Ngọ có Lương tọa thủ, gặp Nguyệt, Linh hội chiếu, là nhiều có tài năng và dĩ nhiên là quý hiển.","d":"Cung Mệnh an tại Tý, Sửu, Dần, Mão, Thìn, Tỵ, Ngọ"},{"c":"Mệnh","s":["Thiên Lương","Thiên Đồng"],"p":"dong_cung","t":"Đàn ông mà cung Mệnh an tại Tỵ, Hợi, có Lương hay Đồng tọa thủ, là người phóng đãng và thích phiêu lưu. Đàn bà là người dâm dật.","d":"Cung Mệnh an tại Tỵ, Hợi"},{"c":"Mệnh","s":["Thiên Lương","Thiên Đồng"],"p":"dong_cung","t":"Cung Mệnh, Thân có Lương hay Đồng miếu, vượng, đắc địa tọa thủ, hay có Lương Đồng tọa thủ đồng cung, nên suốt đời không bao giờ mắc phải tai ương họa hại.","d":"Lương hay Đồng miếu, vượng, đắc địa"},{"c":"Mệnh","s":["Thiên Lương","Thiên Đồng"],"p":"dong_cung","t":"Cung Mệnh an tại Dần, Thân, có Lương, Đồng tọa thủ đồng cung, gặp Cơ, Nguyệt hội chiếu, nên rất thông minh và được hưởng giàu sang trọn đời.","d":"Cung Mệnh an tại Dần, Thân"},{"c":"Mệnh","s":["Thiên Lương","Văn Xương"],"p":"dong_cung","t":"Cung Mệnh có Lương Miếu địa tọa thủ, gặp Xương đồng cung, nên rất quý hiển.","d":"Lương Miếu địa"},{"c":"Mệnh","s":["Thiên Lương"],"p":"tam_hop","t":"Cung Mệnh an tại Tỵ, có Lương tọa thủ, gặp Song Hao, Sát tinh hội hợp, tất khó tránh thoát được tai họa về đau thương hay súng đạn.","d":"Cung Mệnh an tại Tỵ"},{"c":"Mệnh","s":["Thiên Lương","Thiên Mã"],"p":"dong_cung","t":"Cung Mệnh an tại Tý, Hợi có Lương tọa thủ, gặp Mã đồng cung hay xung chiếu, là người phiêu đãng, thích chơi bời, ngao du.","d":"Cung Mệnh an tại Tý, Hợi"},{"c":"Mệnh","s":["Thiên Lương","Thiên Mã"],"p":"dong_cung","t":"Đàn bà mà cung Mệnh an tại Tỵ, Hợi có Lương tọa thủ, gặp Mã đồng cung hay xung chiếu, là người hạ tiện và dâm dật.","d":"Nữ mệnh, Cung Mệnh an tại Tỵ, Hợi"},{"c":"Mệnh","s":["Văn Xương","Văn Khúc","Thiên Đồng","Thiên Lương"],"p":"tam_hop","t":"Người khôn khéo, có nhiều tài năng, sớm hiển đạt và được hưởng giàu sang trọn đời."},{"c":"Mệnh","s":["Văn Xương","Văn Khúc","Thiên Lương"],"p":"xung_chieu","t":"Rất quý hiển, có uy danh lừng lẫy."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-luong-cung-quan-loc', 'sao-cung', 'Thiên Lương tại Quan Lộc', '{"sao":"Thiên Lương","cung":"Quan Lộc","cachCuc":[{"c":"Quan Lộc","s":["Thiên Cơ","Thái Âm","Thiên Đồng","Thiên Lương"],"p":"tam_hop","t":"Nên chuyên nghề thầy thuốc, nếu dạy học cũng nổi tiếng.","d":"tại Dần, Thân, Thìn, Tuất gặp Xương, Khúc, Tả, Hữu"},{"c":"Quan Lộc","s":["Thiên Cơ","Thái Âm","Thiên Đồng","Thiên Lương"],"p":"tam_hop","t":"Vinh hiển trong nghề làm thuốc, được nhiều người kính trọng."},{"c":"Quan Lộc","s":["Thiên Lương","Phá Quân"],"p":"dong_cung","t":"Võ nghiệp hiển đạt, rất dũng mãnh. Hay làm những việc mạo hiểm, sau có uy quyền khá lớn."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-luong-cung-no-boc', 'sao-cung', 'Thiên Lương tại Nô Bộc', '{"sao":"Thiên Lương","cung":"Nô Bộc","cachCuc":[{"c":"Nô Bộc","s":["Tử Vi","Thiên Phủ","Thiên Cơ","Thái Dương","Thái Âm","Thiên Đồng","Thiên Lương"],"p":"dong_cung","t":"Người giúp việc đắc lực, đông đảo, bạn bè khá giả.","d":"sáng sủa tốt đẹp"},{"c":"Nô Bộc","s":["Thiên Lương"],"p":"dong_cung","t":"Được nhiều người kính trọng, yêu mến, hay lui tới những chỗ quyền quý.","d":"đơn thủ tại Tý, Ngọ"},{"c":"Nô Bộc","s":["Thiên Lương"],"p":"dong_cung","t":"Gặp quý nhân.","d":"đơn thủ tại Sửu, Mùi"},{"c":"Nô Bộc","s":["Thiên Lương"],"p":"dong_cung","t":"Nay đây mai đó, chết ở xa nhà.","d":"đơn thủ tại Tỵ, Hợi"},{"c":"Nô Bộc","s":["Thiên Lương","Thiên Đồng"],"p":"dong_cung","t":"Luôn luôn gặp quý nhân phù trợ, được nhiều người kính trọng, buôn bán phát tài."},{"c":"Nô Bộc","s":["Thiên Lương"],"p":"dong_cung","t":"Gặp quý nhân phù trợ, ra ngoài được nhiều người kính trọng, tài lộc dồi dào.","d":"tọa thủ tại Dần, Mão, Thìn, Tỵ, Ngọ"},{"c":"Nô Bộc","s":["Thiên Lương","Thiên Cơ"],"p":"dong_cung","t":"Càng xa nhà càng gặp nhiều may mắn, hay được lui tới chỗ quyền quý, được nhiều người tôn kính vị nể."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('thien-luong-cung-tu-tuc', 'sao-cung', 'Thiên Lương tại Tử Tức', '{"sao":"Thiên Lương","cung":"Tử Tức","cachCuc":[{"c":"Tử Tức","s":["Thiên Phủ","Thiên Tướng","Thiên Lương","Thất Sát","Thiên Đồng","Thái Dương","Thiên Cơ"],"p":"dong_cung","t":"Cung Tử Tức có Chính diệu Nam Đẩu tinh tọa thủ thì con trai nhiều hơn con gái.","d":"Cung Tử Tức có Chính diệu Nam Đẩu tinh tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('that-sat-cung-menh', 'sao-cung', 'Thất Sát tại Mệnh', '{"sao":"Thất Sát","cung":"Mệnh","cachCuc":[{"c":"Mệnh","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Cung Mệnh an tại Tỵ, Hợi có Tử, Sát tọa thủ đồng cung, nên được hưởng phú quý song toàn.","d":"Cung Mệnh an tại Tỵ, Hợi"},{"c":"Mệnh","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Cung Mệnh an tại Tỵ, Hợi có Tử, Sát tọa thủ đồng cung, gặp Tuần, Triệt án ngữ nên suốt đời lao khổ, chỉ có hư danh bề ngoài.","d":"Cung Mệnh an tại Tỵ, Hợi"},{"c":"Mệnh","s":["Tử Vi","Thất Sát","Hóa Quyền"],"p":"dong_cung","t":"Cung Mệnh an tại Tỵ, Hợi có Tử, Sát, Quyền, tọa thủ đồng cung, nên rất rực rỡ tốt đẹp.","d":"Cung Mệnh an tại Tỵ, Hợi"},{"c":"Mệnh","s":["Thất Sát"],"p":"dong_cung","t":"Cung Mệnh an tại Dần, Thân có Thất Sát tọa thủ, tất được hưởng phú quý đến tột bậc.","d":"Cung Mệnh an tại Dần, Thân"},{"c":"Mệnh","s":["Thất Sát"],"p":"dong_cung","t":"Cung Mệnh an tại Tý, Ngọ có Thất Sát tọa thủ, tất được hưởng phú quý đến tột bậc.","d":"Cung Mệnh an tại Tý, Ngọ"},{"c":"Mệnh","s":["Thất Sát","Tử Vi"],"p":"dong_cung","t":"Cung Mệnh an tại Tỵ Tốn cung có Sát, Tử đồng cung, tất được hưởng phú quý đến tột bậc và có uy quyền hiển hách.","d":"Cung Mệnh an tại Tỵ Tốn cung"},{"c":"Mệnh","s":["Thất Sát","Liêm Trinh"],"p":"dong_cung","t":"Cung Mệnh an tại Sửu, Mùi có Sát, Liêm tọa thủ đồng cung, tất nhiên chết ở nơi giữa đường sá, hoặc vì tai nạn xe cộ, hoặc vì dao súng.","d":"Cung Mệnh an tại Sửu, Mùi"},{"c":"Mệnh","s":["Thất Sát","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh có Sát hãm địa tọa thủ (hay có Phá hãm địa tọa thủ) tất phải lìa bỏ gia đình, đi làm ăn ở phương xa.","d":"Cung Mệnh có Sát hãm địa tọa thủ"},{"c":"Mệnh","s":["Thất Sát","Hỏa Tinh","Kình Dương"],"p":"dong_cung","t":"Cung Mệnh có Sát hãm địa tọa thủ, gặp Hỏa, Kình hội hợp là người nghèo hèn, thường làm đồ tể, hàng thịt.","d":"Cung Mệnh có Sát hãm địa tọa thủ"},{"c":"Mệnh","s":["Thất Sát","Thiên Hình"],"p":"dong_cung","t":"Cung Mệnh có Sát miếu, vượng hay đắc địa tọa thủ, gặp Hình đồng cung, là người có oai phong lẫm liệt, như long thần giáng thế.","d":"Cung Mệnh có Sát miếu, vượng hay đắc địa tọa thủ"},{"c":"Mệnh","s":["Thất Sát","Kình Dương"],"p":"dong_cung","t":"Cung Mệnh an tại Ngọ có Sát, Kình tọa thủ đồng cung, gặp nhiều Sát tinh hội hợp, tất hay mắc tai họa khủng khiếp.","d":"Cung Mệnh an tại Ngọ"},{"c":"Mệnh","s":["Thất Sát"],"p":"dong_cung","t":"Cung Mệnh an tại Tuyệt địa có Sát tọa thủ, gặp Kình, Đà hội hợp, tất phải yểu tử như ông Nhan Hồi.","d":"Cung Mệnh an tại Tuyệt địa"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('that-sat-cung-phu-mau', 'sao-cung', 'Thất Sát tại Phụ Mẫu', '{"sao":"Thất Sát","cung":"Phụ Mẫu","cachCuc":[{"c":"Phụ Mẫu","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Cha mẹ phú quý, nhưng bất hòa. Con không hợp với tính cha mẹ. Gia đình ly tán.","d":"Tử Vi, Thất Sát đồng cung"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('that-sat-cung-phuc-duc', 'sao-cung', 'Thất Sát tại Phúc Đức', '{"sao":"Thất Sát","cung":"Phúc Đức","cachCuc":[{"c":"Phúc Đức","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Phải ly tổ, bôn ba mới được hưởng phúc sống lâu, trong họ có nhiều người giàu sang, hiển đạt về võ nghiệp."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('that-sat-cung-dien-trach', 'sao-cung', 'Thất Sát tại Điền Trạch', '{"sao":"Thất Sát","cung":"Điền Trạch","cachCuc":[{"c":"Điền Trạch","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Cơ nghiệp của tổ tiên để lại rất vĩ đại nhưng không giữ gìn được."},{"c":"Điền Trạch","s":["Liêm Trinh","Thất Sát"],"p":"dong_cung","t":"Tự tay lập nghiệp. Thành bại thất thường. Buổi đầu rất vất vả."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('that-sat-cung-quan-loc', 'sao-cung', 'Thất Sát tại Quan Lộc', '{"sao":"Thất Sát","cung":"Quan Lộc","cachCuc":[{"c":"Quan Lộc","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Có uy quyền, nên chuyên về quân sự."},{"c":"Quan Lộc","s":["Liêm Trinh","Thất Sát"],"p":"dong_cung","t":"Chuyên về quân sự nhưng thăng giáng thất thường."},{"c":"Quan Lộc","s":["Thất Sát"],"p":"dong_cung","t":"Có chức vụ lớn lao, uy quyền hiển hách, nhiều người vị nể.","d":"tọa thủ tại Dần, Thân gặp Quyền đồng cung"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('that-sat-cung-no-boc', 'sao-cung', 'Thất Sát tại Nô Bộc', '{"sao":"Thất Sát","cung":"Nô Bộc","cachCuc":[{"c":"Nô Bộc","s":["Thất Sát","Phá Quân","Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Người giúp việc đắc lực, nhưng hay lấn quyền người trên, bạn bè tài giỏi biết nâng đỡ.","d":"sáng sủa tốt đẹp"},{"c":"Nô Bộc","s":["Thất Sát"],"p":"dong_cung","t":"Hay gặp quý nhân, vì có oai nên được nhiều người kính nể, lời nói được nhiều người tin phục.","d":"đơn thủ tại Dần, Thân"},{"c":"Nô Bộc","s":["Thất Sát"],"p":"dong_cung","t":"Được nhiều nể sợ và tin phục. Thường gần nơi quyền quý nhưng không nên ra ngoài nhiều.","d":"đơn thủ tại Tý, Ngọ"},{"c":"Nô Bộc","s":["Thất Sát"],"p":"dong_cung","t":"Ra ngoài rất bất lợi. Lúc chết không được ở gần nhà.","d":"đơn thủ tại Thìn, Tuất"},{"c":"Nô Bộc","s":["Thất Sát","Tử Vi"],"p":"dong_cung","t":"Được nhiều người kính nể, hay lui tới những chỗ quyền quý. Ra ngoài, được hưởng nhiều tài lộc."},{"c":"Nô Bộc","s":["Thất Sát","Liêm Trinh"],"p":"dong_cung","t":"Hay gặp tai nạn ở giữa nơi đường xá, không nên lui tới những nơi có nhiều súng ống gươm đao."},{"c":"Nô Bộc","s":["Thất Sát","Vũ Khúc"],"p":"dong_cung","t":"Có oai phong, lời nói được nhiều người tin phục nhưng hay gặp những tai ương nguy hiểm."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('that-sat-cung-thien-di', 'sao-cung', 'Thất Sát tại Thiên Di', '{"sao":"Thất Sát","cung":"Thiên Di","cachCuc":[{"c":"Thiên Di","s":["Liêm Trinh","Thất Sát"],"p":"dong_cung","t":"Hay gặp tai nạn ở giữa nơi đường xá, không nên lui tới những nơi có nhiều súng ống gươm đao."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('that-sat-cung-tu-tuc', 'sao-cung', 'Thất Sát tại Tử Tức', '{"sao":"Thất Sát","cung":"Tử Tức","cachCuc":[{"c":"Tử Tức","s":["Thiên Phủ","Thiên Tướng","Thiên Lương","Thất Sát","Thiên Đồng","Thái Dương","Thiên Cơ"],"p":"dong_cung","t":"Cung Tử Tức có Chính diệu Nam Đẩu tinh tọa thủ thì con trai nhiều hơn con gái.","d":"Cung Tử Tức có Chính diệu Nam Đẩu tinh tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('that-sat-cung-phu-the', 'sao-cung', 'Thất Sát tại Phu Thê', '{"sao":"Thất Sát","cung":"Phu Thê","cachCuc":[{"c":"Phu Thê","s":["Tử Vi","Thất Sát"],"p":"dong_cung","t":"Tiên trở hậu thành, nên muộn lập gia đình để tránh hình khắc, chia ly."},{"c":"Phu Thê","s":["Liêm Trinh","Thất Sát"],"p":"dong_cung","t":"Hình khắc hay sinh ly, nên muộn lập gia đình để tránh buồn thương."},{"c":"Phu Thê","s":["Thất Sát"],"p":"dong_cung","t":"Nên muộn đường hôn phối, trai lấy vợ tài giỏi nhưng hay ghen.","d":"Đơn thủ tại Dần, Thân"},{"c":"Phu Thê","s":["Thất Sát"],"p":"dong_cung","t":"Vợ chồng hay bất hòa, nếu sớm lập gia đình tất phải hình khắc hay chia ly.","d":"Đơn thủ tại Tý, Ngọ"},{"c":"Phu Thê","s":["Thất Sát"],"p":"dong_cung","t":"Trai hay gái phải hai ba lần lập gia đình, rất nhiều tai ương xảy ra.","d":"Đơn thủ tại Thìn, Tuất"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('pha-quan-cung-menh', 'sao-cung', 'Phá Quân tại Mệnh', '{"sao":"Phá Quân","cung":"Mệnh","cachCuc":[{"c":"Mệnh","s":["Tử Vi","Vũ Khúc","Phá Quân"],"p":"tam_hop","t":"Cung Mệnh có Tử, Vũ hay Phá tọa thủ, lại gặp Kình, Đà hội hợp nên không thích công danh mà chỉ thích buôn bán, nhưng cũng khá giả."},{"c":"Mệnh","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh an tại Tứ Mộ, có Tử hay Phá tọa thủ là người gian quyệt, bất trung, bất hiếu.","d":"Cung Mệnh an tại Tứ Mộ"},{"c":"Mệnh","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh an tại Thìn, Tuất, Sửu, Mùi có Tử hay Phá tọa thủ, gặp nhiều sao sáng sủa tốt đẹp hội hợp nên được hưởng phú quý đến tột bực.","d":"Cung Mệnh an tại Thìn, Tuất, Sửu, Mùi"},{"c":"Mệnh","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh an tại Sửu, có Tử, Phá tọa thủ đồng cung nếu không gặp Tả, Hữu và nhiều sao sáng sủa tốt đẹp hội hợp, tất là người gian tham độc ác.","d":"Cung Mệnh an tại Sửu"},{"c":"Mệnh","s":["Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh an tại Tỵ, Hợi có Vũ, Phá tọa thủ đồng cung, là người tham lận và bất lương.","d":"an tại Tỵ, Hợi"},{"c":"Mệnh","s":["Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh an tại Tỵ, Hợi có Vũ, Phá tọa thủ đồng cung nên không thể gìn giữ được của cải hay sản nghiệp của tiền nhân.","d":"an tại Tỵ, Hợi"},{"c":"Mệnh","s":["Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh có Vũ, Phá tọa thủ đồng cung, tất phải bỏ nhà đi kiếm ăn ở phương xa, và suốt đời vất vả lao khổ."},{"c":"Mệnh","s":["Vũ Khúc","Phá Quân","Văn Xương","Văn Khúc"],"p":"dong_cung","t":"Cung Mệnh có Vũ, Phá tọa thủ đồng cung, gặp Xương, Khúc đồng cung là người thông minh, khéo tay nên chuyên về kỹ nghệ máy móc."},{"c":"Mệnh","s":["Tham Lang","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh có Tham, Vũ tọa thủ đồng cung, gặp Phá chiếu, nhưng không gặp nhiều sao sáng sủa tốt đẹp hội hợp, tất hay say mê rượu ngon gái đẹp mà hại đến thân.","d":"Không gặp nhiều sao sáng sủa tốt đẹp hội hợp"},{"c":"Mệnh","s":["Thất Sát","Phá Quân"],"p":"dong_cung","t":"Cung Mệnh có Sát hãm địa tọa thủ (hay có Phá hãm địa tọa thủ) tất phải lìa bỏ gia đình, đi làm ăn ở phương xa.","d":"Cung Mệnh có Sát hãm địa tọa thủ"},{"c":"Mệnh","s":["Phá Quân"],"p":"dong_cung","t":"Cung Mệnh an tại Tý, Ngọ, Thìn, Tuất, Dần, Thân có Phá đơn thủ là người không sát suốt, hay nghe nịnh hót.","d":"Cung Mệnh an tại Tý, Ngọ, Thìn, Tuất, Dần, Thân"},{"c":"Mệnh","s":["Phá Quân","Tham Lang"],"p":"dong_cung","t":"Cung Mệnh có Phá tọa thủ, gặp Lộc, Mã hội hợp: đàn ông hay chơi bời hoang đãng, đàn bà rất dâm dật.","d":"Cung Mệnh có Phá tọa thủ"},{"c":"Mệnh","s":["Phá Quân"],"p":"dong_cung","t":"Người gian ác bất nhân.","d":"Cung Mệnh an tại Thìn, Tuất"},{"c":"Mệnh","s":["Phá Quân","Khoa","Tuần"],"p":"dong_cung","t":"Hoạnh phát danh tài, thẳng thắn, lương thiện.","d":"Cung Mệnh an tại Thìn, Tuất"},{"c":"Mệnh","s":["Phá Quân"],"p":"dong_cung","t":"Người hay gắt gỏng, nói năng thô lỗ.","d":"Cung Mệnh an tại Ngọ"},{"c":"Mệnh","s":["Phá Quân","Lộc","Thiếu Dương"],"p":"dong_cung","t":"Rất vui tính, hay nói đùa bỡn.","d":"Cung Mệnh an tại Ngọ"},{"c":"Mệnh","s":["Phá Quân"],"p":"dong_cung","t":"Người cương quả, gặp được sự nghiệp lớn trong thời loạn.","d":"Cung Mệnh an tại tứ Mộ"},{"c":"Mệnh","s":["Phá Quân","Hình","Lộc"],"p":"dong_cung","t":"Có uy quyền hiển hách, danh tiếng lừng lẫy.","d":"Cung Mệnh an tại tứ Mộ"},{"c":"Mệnh","s":["Văn Xương","Văn Khúc","Phá Quân"],"p":"dong_cung","t":"Suốt đời phải tao tâm khổ tứ và hay bị bắt bớ giam cầm."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('pha-quan-cung-phu-mau', 'sao-cung', 'Phá Quân tại Phụ Mẫu', '{"sao":"Phá Quân","cung":"Phụ Mẫu","cachCuc":[{"c":"Phụ Mẫu","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Trong nhà hay có sự bất hòa: cha mẹ khá giả. Nhưng sớm khắc một trong hai thân, hay phải xa cách từ lúc thiếu thời.","d":"Tử Vi, Phá Quân đồng cung"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('pha-quan-cung-phuc-duc', 'sao-cung', 'Phá Quân tại Phúc Đức', '{"sao":"Phá Quân","cung":"Phúc Đức","cachCuc":[{"c":"Phúc Đức","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Lao tâm khổ tứ, chẳng được yên thân, phải lìa bỏ quê hương mới khá giả và sống lâu, họ hàng ly tán."},{"c":"Phúc Đức","s":["Phá Quân"],"p":"dong_cung","t":"Được hưởng phúc, sống lâu, nhưng nên lập nghiệp ở nơi thật xa quê hương.","d":"Đơn thủ tại Tý, Ngọ"},{"c":"Phúc Đức","s":["Phá Quân"],"p":"dong_cung","t":"Không được hưởng phúc dồi dào. Phải ly tán, sớm xa gia đình, mới mong được yên thân.","d":"Đơn thủ tại Thìn, Tuất"},{"c":"Phúc Đức","s":["Phá Quân"],"p":"dong_cung","t":"Bạc phúc nên giảm thọ. Khó tránh được tai họa.","d":"Đơn thủ tại Dần, Thân"},{"c":"Phúc Đức","s":["Phá Quân","Tử Vi"],"p":"dong_cung","t":"Lao tâm khổ tứ, chẳng được yên thân. Phải lìa bỏ quê hương mới khá giả và sống lâu.","d":"Tử đồng cung"},{"c":"Phúc Đức","s":["Phá Quân","Liêm Trinh"],"p":"dong_cung","t":"Vất vả lao khổ, phải xa quê hương mới sống lâu.","d":"Liêm đồng cung"},{"c":"Phúc Đức","s":["Phá Quân","Vũ Khúc"],"p":"dong_cung","t":"Phải lập nghiệp ở xa quê hương, phải sớm xa gia đình mới mong được yên thân hưởng phúc sống lâu.","d":"Vũ đồng cung"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('pha-quan-cung-dien-trach', 'sao-cung', 'Phá Quân tại Điền Trạch', '{"sao":"Phá Quân","cung":"Điền Trạch","cachCuc":[{"c":"Điền Trạch","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Phá tán tổ nghiệp, hay lìa bỏ tổ nghiệp. Về sau tạo lập ở nơi xa mà bền vững."},{"c":"Điền Trạch","s":["Liêm Trinh","Phá Quân"],"p":"dong_cung","t":"Lập nghiệp ở buổi đầu hay bị thất bại, phá tán. Về sau mới được bền vững."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('pha-quan-cung-quan-loc', 'sao-cung', 'Phá Quân tại Quan Lộc', '{"sao":"Phá Quân","cung":"Quan Lộc","cachCuc":[{"c":"Quan Lộc","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Thành công trong võ nghiệp nhưng thăng giáng thất thường."},{"c":"Quan Lộc","s":["Liêm Trinh","Phá Quân"],"p":"dong_cung","t":"Nên chuyên về kỹ nghệ, hay thương mại."},{"c":"Quan Lộc","s":["Phá Quân"],"p":"dong_cung","t":"Võ nghiệp hiển đạt, nhưng thăng giáng thất thường. Lập công danh trong thời loạn.","d":"đơn thủ tại Tý, Ngọ"},{"c":"Quan Lộc","s":["Phá Quân"],"p":"dong_cung","t":"Thành công về quân sự, nổi tiếng về sự nghiệp chính trị. Có uy quyền hiển hách.","d":"đơn thủ tại Thìn, Tuất"},{"c":"Quan Lộc","s":["Phá Quân"],"p":"dong_cung","t":"Công danh trắc trở, chức vị nhỏ thấp. Nếu giàu sang cũng chẳng được lâu bền.","d":"đơn thủ tại Dần, Thân"},{"c":"Quan Lộc","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Thành công trong võ nghiệp nhưng thăng giáng thất thường. Nếu đi buôn cũng phát đạt."},{"c":"Quan Lộc","s":["Liêm Trinh","Phá Quân"],"p":"dong_cung","t":"Nên chuyên về kỹ nghệ, hay thương mại. Nếu chen chân vào đường công danh, tất chẳng được xứng ý toại lòng."},{"c":"Quan Lộc","s":["Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Xuất thân bằng võ nghiệp, nhưng rất chật vật. Nếu kinh doanh buôn bán, rất được xứng ý toại lòng."},{"c":"Quan Lộc","s":["Thiên Lương","Phá Quân"],"p":"dong_cung","t":"Võ nghiệp hiển đạt, rất dũng mãnh. Hay làm những việc mạo hiểm, sau có uy quyền khá lớn."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('pha-quan-cung-no-boc', 'sao-cung', 'Phá Quân tại Nô Bộc', '{"sao":"Phá Quân","cung":"Nô Bộc","cachCuc":[{"c":"Nô Bộc","s":["Thất Sát","Phá Quân","Liêm Trinh","Tham Lang"],"p":"dong_cung","t":"Người giúp việc đắc lực, nhưng hay lấn quyền người trên, bạn bè tài giỏi biết nâng đỡ.","d":"sáng sủa tốt đẹp"},{"c":"Nô Bộc","s":["Phá Quân"],"p":"dong_cung","t":"Nhiều người nể sợ, tài lộc dễ kiếm, nhưng đôi khi mắc tai nạn nguy hiểm.","d":"đơn thủ tại Tý, Ngọ"},{"c":"Nô Bộc","s":["Phá Quân"],"p":"dong_cung","t":"Hay mắc tai nạn nhất là về xe cộ và ác thú, hay gặp những kẻ rình ám hại.","d":"đơn thủ tại Dần, Thân"},{"c":"Nô Bộc","s":["Phá Quân"],"p":"dong_cung","t":"May đi liền với rủi, người kính trọng cũng có mà ghen ghét muốn hại cũng nhiều.","d":"đơn thủ tại Thìn, Tuất"},{"c":"Nô Bộc","s":["Tham Lang","Phá Quân"],"p":"tam_hop","t":"Hay mắc tai nạn xe cộ, dao, súng. Nếu không cũng bị đánh đập giam cầm."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('pha-quan-cung-thien-di', 'sao-cung', 'Phá Quân tại Thiên Di', '{"sao":"Phá Quân","cung":"Thiên Di","cachCuc":[{"c":"Thiên Di","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Ra ngoài nhiều hơn là ở nhà, gặp quý nhân phù trợ, nhưng lúc về già thường nhắm mắt ở xa bản quán."},{"c":"Thiên Di","s":["Liêm Trinh","Phá Quân"],"p":"dong_cung","t":"Xa nhà không được lợi ích, may ít rủi nhiều, sau này chết ở xa nhà."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('pha-quan-cung-tu-tuc', 'sao-cung', 'Phá Quân tại Tử Tức', '{"sao":"Phá Quân","cung":"Tử Tức","cachCuc":[{"c":"Tử Tức","s":["Thái Âm","Tham Lang","Cự Môn","Liêm Trinh","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Tử Tức có Chính diệu Bắc Đẩu tinh tọa thủ thì con gái nhiều hơn con trai.","d":"Cung Tử Tức có Chính diệu Bắc Đẩu tinh tọa thủ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('pha-quan-cung-phu-the', 'sao-cung', 'Phá Quân tại Phu Thê', '{"sao":"Phá Quân","cung":"Phu Thê","cachCuc":[{"c":"Phu Thê","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Phải hình khắc hay chia ly, sống chung tiếp hờn giận."},{"c":"Phu Thê","s":["Liêm Trinh","Phá Quân"],"p":"dong_cung","t":"Vợ chồng bất hòa, hay xa cách, sinh kế khó khăn."},{"c":"Phu Thê","s":["Phá Quân"],"p":"dong_cung","t":"Vợ chồng khá giả nhưng nên muộn đường hôn phối.","d":"Đơn thủ tại Tý, Ngọ"},{"c":"Phu Thê","s":["Phá Quân"],"p":"dong_cung","t":"Hình khắc không thể tránh được, trai lấy vợ bất nhân, gái lấy chồng bất nghĩa.","d":"Đơn thủ tại Dần, Thân"},{"c":"Phu Thê","s":["Phá Quân"],"p":"dong_cung","t":"Nên muộn lập gia đình, nếu không tất phải hai ba lần chắp nối đường tơ.","d":"Đơn thủ tại Thìn, Tuất"},{"c":"Phu Thê","s":["Tử Vi","Phá Quân"],"p":"dong_cung","t":"Phải hình khắc hay chia ly, sống chung tiếp hờn giận."},{"c":"Phu Thê","s":["Liêm Trinh","Phá Quân"],"p":"dong_cung","t":"Vợ chồng bất hòa, hay xa cách nhau, sinh kế khó khăn."},{"c":"Phu Thê","s":["Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Vợ chồng đều thao lược nhưng nếu sớm gặp nhau tất phải hình khắc."},{"c":"Phu Thê","s":["Phá Quân","Tuần","Triệt"],"p":"dong_cung","t":"Ba lần lập gia đình.","d":"Án ngữ"}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('pha-quan-cung-huynh-de', 'sao-cung', 'Phá Quân tại Huynh Đệ', '{"sao":"Phá Quân","cung":"Huynh Đệ","cachCuc":[{"c":"Huynh Đệ","s":["Thái Âm","Tham Lang","Cự Môn","Liêm Trinh","Vũ Khúc","Phá Quân"],"p":"dong_cung","t":"Cung Huynh Đệ có các sao Bắc Đẩu tinh, chị em gái nhiều hơn anh em trai.","d":"Cung Huynh Đệ có Chính diệu Bắc Đẩu tinh tọa thủ"},{"c":"Huynh Đệ","s":["Phá Quân","Thiên Tướng"],"p":"dong_cung","t":"Anh chị em có người không đứng đắn, ưa việc liễu ngõ hoa tường."},{"c":"Huynh Đệ","s":["Phá Quân","Thiên Hình","Địa Không"],"p":"dong_cung","t":"Anh chị em làm hại nhau."}]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
insert into public.thu_vien_muc (slug, bo_suu_tap, ten, xuong) values ('nap-am-hai-trung-kim', 'nap-am', 'Hải Trung Kim', '{"hanh":"Kim","canChi":["Giáp Tý","Ất Sửu"]}'::jsonb) on conflict (slug) do update set xuong = excluded.xuong;
